const COMP = [["Rechtsfähigkeit","Ich unterscheide, wer Rechte haben kann und wer selbst wirksam handeln kann."],["Geschäftsfähigkeit","Ich ordne Kunden anhand ihres Alters ein und erkenne eine nichtige eigene Erklärung."],["Rechtlicher Vorteil","Ich erkenne, ob ein Geschäft eine rechtliche Pflicht begründet."],["Zustimmung","Ich prüfe, wann und wozu die gesetzlichen Vertreter zugestimmt haben."],["§ 110 BGB","Ich prüfe, ob die Leistung vollständig und mit zulässig überlassenen Mitteln erbracht wurde."]];
const BANK = [{"id":0,"l":1,"c":0,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Ein Fahrrad für ein Baby","scene":"Ein neugeborenes Kind bekommt ein Fahrrad geschenkt. Seine Eltern nehmen es in seinem Namen an.","ask":"Welche Aussagen passen?","options":["Rechte entstehen erst ab sieben.","Das Kind kann Eigentümer werden.","Weil das Kind kein Geld hat, kann ihm nichts gehören.","Die Eltern werden allein wegen der Vertretung Eigentümer.","Das Kind hat Rechte.","Das Kind kann selbst einen Kaufvertrag schließen."],"answer":[1,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Rechtsfähigkeit beginnt mit der vollendeten Geburt. Die Eltern handeln für das Kind.","hint":"Trenne die Frage, wem das Rad gehören kann, von der Frage, wer handelt.","steps":"Unterstreiche die Person, die ein Recht erhalten kann. Prüfe getrennt, wer die Erklärung abgibt.","example":"Bei einem Geschenk kann das Kind Eigentümer sein, während die gesetzlichen Vertreter die Annahme erklären.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":1,"l":1,"c":0,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Darf besitzen oder selbst handeln?","scene":"Ein 6-Jähriger hat einen geschenkten Helm. Er möchte im Laden selbst einen zweiten Helm kaufen.","ask":"Welche Aussagen unterscheiden beide Fragen richtig?","options":["Eigentum am ersten Helm macht ihn voll geschäftsfähig.","Sein eigener Kaufwunsch muss zusätzlich unter dem Gesichtspunkt der Geschäftsfähigkeit geprüft werden.","Der Verkäufer entscheidet, ob das Kind rechtsfähig ist.","Dass ihm der erste Helm gehören kann, zeigt seine Rechtsfähigkeit.","Der zweite Helm gehört ihm bereits durch seinen Kaufwunsch.","Wer unter sieben ist, kann grundsätzlich keine Rechte haben."],"answer":[1,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Das Eigentum betrifft die Rechtsfähigkeit. Für eigene wirksame Erklärungen kommt es auf die Geschäftsfähigkeit an.","hint":"Ordne Besitz oder Eigentum einer anderen Frage zu als dem selbstständigen Kauf.","steps":"Unterstreiche die Person, die ein Recht erhalten kann. Prüfe getrennt, wer die Erklärung abgibt.","example":"Bei einem Geschenk kann das Kind Eigentümer sein, während die gesetzlichen Vertreter die Annahme erklären.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":2,"l":1,"c":1,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Die Altersstufen einordnen","scene":"An einem Vormittag kommen Kunden im Alter von 6, 15 und 18 Jahren vorbei. Weitere Umstände spielen im Fall keine Rolle.","ask":"Welche Zuordnungen stimmen?","options":["15 Jahre: beschränkt geschäftsfähig.","18 Jahre: altersbedingt beschränkt geschäftsfähig.","18 Jahre: im Regelfall voll geschäftsfähig.","15 Jahre: voll geschäftsfähig.","6 Jahre: geschäftsunfähig.","6 Jahre: beschränkt geschäftsfähig."],"answer":[0,2,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Unter sieben ist man geschäftsunfähig. Minderjährige von sieben bis einschließlich 17 sind beschränkt geschäftsfähig. Ab 18 ist man im Regelfall voll geschäftsfähig.","hint":"Achte auf den siebten und den achtzehnten Geburtstag.","steps":"Ordne zuerst das Alter am Tag des Geschäfts ein. Prüfe danach, von wem die Erklärung stammt.","example":"Das Alter einer Person wird am Tag der eigenen Erklärung geprüft. Ein späterer Geburtstag ändert den damaligen Stand nicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":3,"l":1,"c":1,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Eine Fünfjährige kauft allein","scene":"Ella ist 5 Jahre alt und bezahlt einen Reflektor selbst bar. Niemand handelt in ihrem Namen.","ask":"Wie ist ihre eigene Willenserklärung zu beurteilen?","options":["Der Kassenvorgang macht sie voll geschäftsfähig.","Sie ist als lediglich rechtlicher Vorteil wirksam.","Sie ist wegen der Barzahlung wirksam.","Sie bleibt bis zur Zahlung schwebend unwirksam.","Sie ist nichtig.","Sie ist wegen des geringen Preises wirksam."],"answer":[4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Ella ist unter sieben. Ihre eigene Willenserklärung ist nach §§ 104 und 105 BGB nichtig. Ihre Zahlung ändert daran nichts.","hint":"Kläre zuerst das Alter. Prüfe die Zahlung erst danach.","steps":"Ordne zuerst das Alter am Tag des Geschäfts ein. Prüfe danach, von wem die Erklärung stammt.","example":"Das Alter einer Person wird am Tag der eigenen Erklärung geprüft. Ein späterer Geburtstag ändert den damaligen Stand nicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":4,"l":1,"c":2,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Eine Klingel als Geschenk","scene":"Lukas ist 13. Eine Nachbarin schenkt ihm eine Klingel. Das Geschenk ist frei von Pflichten und Bedingungen.","ask":"Welche Aussagen treffen zu?","options":["Eine Zustimmung der Eltern ist allein wegen seines Alters immer nötig.","Das Geschenk muss vollständig bezahlt werden.","Die Annahme ist lediglich rechtlich vorteilhaft.","Er kann die Klingel selbst annehmen.","Die Schenkung begründet in diesem Fall eine Zahlungspflicht.","Er ist wegen der Klingel voll geschäftsfähig."],"answer":[2,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Lukas bekommt einen rechtlichen Vorteil ohne zusätzliche Verpflichtung. Deshalb braucht er für diese Annahme keine Einwilligung.","hint":"Suche nach einer Pflicht, die durch die Annahme entstehen würde.","steps":"Lies, welche Folgen die Annahme hat. Suche nach einer Geldzahlung oder einer anderen rechtlichen Pflicht.","example":"Ein Preisnachlass spart Geld. Beim Kauf bleibt trotzdem eine Zahlungspflicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":5,"l":1,"c":2,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Ein günstiger Helm bleibt ein Kauf","scene":"Ein stark verbilligter Helm wird einem 15-Jährigen für 10 Euro verkauft.","ask":"Warum ist das Geschäft nicht lediglich rechtlich vorteilhaft?","options":["Der frühere Preis ist entscheidend.","Der Kauf verpflichtet den Kunden zur Zahlung.","Ein Helm darf nur Volljährigen gehören.","Ein Rabatt macht seine Erklärung nichtig.","Global Bike verkauft Zubehör.","Der Helm muss vor Regen schützen."],"answer":[1],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Auch ein günstiger Kauf verpflichtet zur Zahlung. Der finanzielle Vorteil des Rabatts ändert die rechtliche Pflicht nicht.","hint":"Suche nach der Gegenleistung im Vertrag.","steps":"Lies, welche Folgen die Annahme hat. Suche nach einer Geldzahlung oder einer anderen rechtlichen Pflicht.","example":"Ein Preisnachlass spart Geld. Beim Kauf bleibt trotzdem eine Zahlungspflicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":6,"l":1,"c":3,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Vorher und nachher","scene":"Eine Zustimmung kann vor oder nach dem Einkauf eingeholt werden.","ask":"Welche Begriffe passen?","options":["Eine Genehmigung ist die ursprüngliche Kaufentscheidung des Kindes.","Nach dem Vertrag: Genehmigung.","Einwilligung wird immer nach dem Kauf erteilt.","Vor dem Vertrag: Einwilligung.","Vorher und nachher werden rechtlich gleich benannt.","Beide sind Formen der Zustimmung."],"answer":[1,3,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"§§ 183 und 184 BGB unterscheiden Einwilligung vor der Erklärung und Genehmigung danach.","hint":"Ordne die Zeitwörter „vorher“ und „nachher“.","steps":"Markiere den Zeitpunkt des Vertrags und den Stand der Zustimmung. Entscheide erst danach, ob der Fall offen ist.","example":"Die Einwilligung liegt vor dem Vertrag. Eine erst danach erteilte Zustimmung heißt Genehmigung.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":7,"l":1,"c":3,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Kauf auf Rechnung erlaubt","scene":"Die Eltern erlauben ihrer 14-jährigen Tochter vorab ausdrücklich, eine Tasche auf Rechnung zu kaufen. Sie bestellt genau vereinbarungsgemäß.","ask":"Welche Aussagen treffen zu?","options":["Die Zustimmung ist eine Einwilligung.","Der Taschengeldparagraph ist die einzige Möglichkeit für eine wirksame Bestellung.","Der Vertrag wird grundsätzlich erst bei Zahlung wirksam.","Der Vertrag ist mit dieser Einwilligung wirksam.","Die Zustimmung muss anschließend noch einmal als Genehmigung erklärt werden.","Der Vertrag ist nichtig, weil Rechnungszahlung vorgesehen ist."],"answer":[0,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die ausdrückliche Einwilligung umfasst gerade den Kauf auf Rechnung. Eine sofortige Zahlung nach § 110 BGB muss dafür nicht geprüft werden.","hint":"Vergleiche, was erlaubt wurde und was tatsächlich bestellt wird.","steps":"Markiere den Zeitpunkt des Vertrags und den Stand der Zustimmung. Entscheide erst danach, ob der Fall offen ist.","example":"Die Einwilligung liegt vor dem Vertrag. Eine erst danach erteilte Zustimmung heißt Genehmigung.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":8,"l":1,"c":3,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Ein Auftrag ist noch offen","scene":"Tom ist 16. Er bestellt ohne Einwilligung auf Rechnung. Es wurde nichts bezahlt; die Eltern haben noch nicht entschieden.","ask":"Was gilt bis zur Entscheidung?","options":["Die Rechnung macht den Vertrag sofort wirksam.","§ 110 BGB ist ohne Zahlung automatisch erfüllt.","Der Vertrag ist schwebend unwirksam.","Der Vertrag ist bereits endgültig unwirksam.","Der Vertrag ist von Anfang an nichtig.","Der Kauf ist als Geschenk wirksam."],"answer":[2],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Ohne vorherige Zustimmung hängt der Vertrag hier vorerst von der nachträglichen Genehmigung ab.","hint":"Ist die Zustimmung schon verweigert oder steht sie noch aus?","steps":"Markiere den Zeitpunkt des Vertrags und den Stand der Zustimmung. Entscheide erst danach, ob der Fall offen ist.","example":"Die Einwilligung liegt vor dem Vertrag. Eine erst danach erteilte Zustimmung heißt Genehmigung.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":9,"l":1,"c":4,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"§ 110: Was muss geprüft werden?","scene":"Ein beschränkt geschäftsfähiger Minderjähriger kauft ohne ausdrückliche Zustimmung und beruft sich auf Taschengeld.","ask":"Welche Merkmale gehören zur Prüfung nach § 110 BGB?","options":["Die Mittel stammen vom gesetzlichen Vertreter oder mit dessen Zustimmung von einem Dritten.","Die erste Rate reicht immer aus.","Geschäftsunfähige werden durch Taschengeld beschränkt geschäftsfähig.","Die Mittel müssen zu diesem Zweck oder zur freien Verfügung überlassen sein.","Die vereinbarte Leistung muss vollständig erbracht sein.","Der Preis ist automatisch erlaubt, wenn er unter 50 Euro liegt."],"answer":[0,3,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Vollständige Leistung und zulässig überlassene Mittel müssen gemeinsam geprüft werden. Das Gesetz nennt keine feste Eurogrenze.","hint":"Notiere zwei Prüfbereiche: Geld und Leistung.","steps":"Prüfe zuerst, ob die Leistung vollständig vorliegt. Vergleiche dann Herkunft und erlaubte Verwendung aller eingesetzten Mittel.","example":"Wer nur die erste von zwei Raten zahlt, hat die vereinbarte Leistung noch nicht vollständig erbracht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":10,"l":1,"c":4,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Geld mit festem Zweck","scene":"Max ist 15. Seine Eltern geben ihm Geld ausdrücklich nur für Schulmaterial. Er zahlt damit ohne Zustimmung ein Fahrradschloss vollständig.","ask":"Welche Aussagen treffen zu?","options":["Der Vertrag hängt zunächst von der Genehmigung ab.","Die vollständige Zahlung beseitigt die Zweckbindung.","Ein Schloss ist immer Schulmaterial.","Weil Max 15 ist, ist seine Erklärung generell nichtig.","Die Zahlung verletzt die Zweckbindung.","§ 110 BGB macht diesen Kauf damit nicht wirksam."],"answer":[0,4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Das Geld war für einen anderen Zweck bestimmt. Ohne Einwilligung und ohne wirksame Leistung aus zulässig überlassenen Mitteln bleibt der Vertrag zunächst offen.","hint":"Vergleiche den erlaubten und den tatsächlichen Kaufzweck.","steps":"Prüfe zuerst, ob die Leistung vollständig vorliegt. Vergleiche dann Herkunft und erlaubte Verwendung aller eingesetzten Mittel.","example":"Wer nur die erste von zwei Raten zahlt, hat die vereinbarte Leistung noch nicht vollständig erbracht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":11,"l":1,"c":4,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Alle Raten beglichen","scene":"Eine 17-Jährige hat ohne Einwilligung einen Ratenkauf vereinbart. Sie hat alle Raten aus dem frei verfügbaren Geld ihrer Eltern gezahlt. Es bestehen keine weiteren Pflichten. Es wurde keine Genehmigung verweigert.","ask":"Welche Aussagen passen zum Ergebnis?","options":["Eine noch offene erste Rate wäre gleich zu behandeln.","§ 110 BGB kann den Vertrag von Anfang an wirksam machen.","Mit der ersten Rate gilt jede Ratenabrede sofort als erfüllt.","Die vereinbarte Leistung ist erbracht.","Für frei verfügbares Geld gibt es stets eine 50-Euro-Grenze.","Nur Volljährige können eine vollständige Leistung erbringen."],"answer":[1,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Erst die vollständige Leistung mit zulässigen Mitteln erfüllt im Fall die Voraussetzungen. Das Gesetz behandelt den Vertrag dann als von Anfang an wirksam.","hint":"Prüfe, ob noch eine Rate oder eine weitere Pflicht offensteht.","steps":"Prüfe zuerst, ob die Leistung vollständig vorliegt. Vergleiche dann Herkunft und erlaubte Verwendung aller eingesetzten Mittel.","example":"Wer nur die erste von zwei Raten zahlt, hat die vereinbarte Leistung noch nicht vollständig erbracht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":12,"l":2,"c":0,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Eine falsche Kundennotiz berichtigen","scene":"Übungsvariante: Für ein Baby haben die Eltern ein Geschenk angenommen. Im Kundenblatt steht: „Weil es Eigentümer sein kann, darf es Verträge selbst schließen.“","ask":"Welche Änderungen machen den Vermerk richtig?","options":["Ein Baby kann erst bei eigener Barzahlung Rechte erwerben.","Das Eigentum muss den Eltern zugeschrieben werden.","Der Vermerk bleibt gleich, wenn Besitz und Eigentum vertauscht werden.","Die Eltern handeln als Vertreter. Die eigene Geschäftsfähigkeit folgt aus der Rechtsfähigkeit nicht.","Das Geschenk macht das Baby beschränkt geschäftsfähig.","Die Möglichkeit, Rechte zu haben, bleibt im Vermerk stehen."],"answer":[3,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Das Baby ist rechtsfähig. Die Eltern erklären die Annahme für das Kind; die eigene Geschäftsfähigkeit wird davon nicht verändert.","hint":"Korrigiere nur die Schlussfolgerung über das selbstständige Handeln.","steps":"Unterstreiche die Person, die ein Recht erhalten kann. Prüfe getrennt, wer die Erklärung abgibt.","example":"Bei einem Geschenk kann das Kind Eigentümer sein, während die gesetzlichen Vertreter die Annahme erklären.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":13,"l":2,"c":0,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Zwei Fragen für den Verkauf trennen","scene":"Übungsvariante: Eine Verkäuferin fragt, ob der 6-jährige Eigentümer eines geschenkten Rads einen beworbenen Radkorb selbst auf Rechnung kaufen kann.","ask":"Wie ordnest du ihre Fragen ein, bevor du über den Kauf entscheidest?","options":["Das Eigentum am Rad betrifft seine Rechtsfähigkeit.","Die Reihenfolge lautet: zuerst Rechnung schreiben, dadurch wird er rechtsfähig.","Eigentum entscheidet allein über die Wirksamkeit des neuen Kaufs.","Die Rechte am Rad verleihen ihm keine Befugnis zur eigenen wirksamen Bestellung.","Sein Besitz des Rads bestätigt zugleich die Volljährigkeit.","Der selbst erklärte Rechnungskauf betrifft seine Geschäftsfähigkeit."],"answer":[0,3,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Dass einem Kind ein Gegenstand gehören kann, ersetzt keine Prüfung seiner eigenen Willenserklärung zum neuen Geschäft.","hint":"Ein vorhandenes Recht sagt noch nichts über die Möglichkeit aus, selbst einen Vertrag zu schließen.","steps":"Unterstreiche die Person, die ein Recht erhalten kann. Prüfe getrennt, wer die Erklärung abgibt.","example":"Bei einem Geschenk kann das Kind Eigentümer sein, während die gesetzlichen Vertreter die Annahme erklären.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":14,"l":2,"c":1,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Am selben Tag richtig zuordnen","scene":"Übungsvariante: Eine Kundin ist eben 7 geworden; ihr Bruder wird erst morgen 18. Eine weitere Kundin ist 19. Es sind keine Sonderumstände bekannt.","ask":"Welche Zeilen sind richtig?","options":["Weitere Kundin: altersbedingt erst ab dem 21. Geburtstag voll geschäftsfähig.","Bruder: bis zum 18. Geburtstag beschränkt geschäftsfähig.","Bruder: schon heute wegen der bevorstehenden Volljährigkeit voll geschäftsfähig.","Kundin: jetzt beschränkt geschäftsfähig.","Weitere Kundin: im Regelfall voll geschäftsfähig.","Erste Kundin: bis zum achten Geburtstag noch geschäftsunfähig."],"answer":[1,3,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Altersgrenzen gelten am jeweiligen Geburtstag. Im Fall werden die Personen anhand des aktuellen Alters eingeordnet.","hint":"Nutze „heute“ als Stichtag.","steps":"Ordne zuerst das Alter am Tag des Geschäfts ein. Prüfe danach, von wem die Erklärung stammt.","example":"Das Alter einer Person wird am Tag der eigenen Erklärung geprüft. Ein späterer Geburtstag ändert den damaligen Stand nicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":15,"l":2,"c":1,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Ein Kassenvorgang führt in die Irre","scene":"Übungsvariante: Ein 5-Jähriger hat selbst vier Euro für eine Fahrradklingel gegeben. Das Team findet einen Kassenbeleg und hält den Vorgang deshalb für wirksam.","ask":"Welche Korrektur gehört ins Fallprotokoll?","options":["Die Erklärung gilt allein wegen des niedrigen Preises.","Das Kind ist wegen des Belegs rechtsfähig geworden.","Der Vorgang ist schwebend unwirksam wie ein offener Rechnungskauf eines 16-Jährigen.","Der Beleg ist kein Ersatz für eine wirksame eigene Willenserklärung des Kindes.","Weil der Käufer unter sieben ist, ist seine eigene Erklärung nichtig.","Eine Kassenbuchung führt zur Volljährigkeit."],"answer":[3,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Zahlung dokumentiert eine Geldübergabe. Der eigene Vertragsschluss scheitert an der Geschäftsunfähigkeit des Kindes.","hint":"Was beweist der Beleg tatsächlich?","steps":"Ordne zuerst das Alter am Tag des Geschäfts ein. Prüfe danach, von wem die Erklärung stammt.","example":"Das Alter einer Person wird am Tag der eigenen Erklärung geprüft. Ein späterer Geburtstag ändert den damaligen Stand nicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":16,"l":2,"c":2,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Ein Geschenk mit Bedingungen prüfen","scene":"Übungsvariante: Ein 13-Jähriger kann ein kostenloses Fahrradlicht erhalten. Er müsste dafür verbindlich zwei Arbeitsstunden im Lager leisten. Ohne Leistung gibt es kein Geschenk.","ask":"Welche Aussagen sind für die Prüfung wichtig?","options":["Die zugesagte Arbeit wäre eine rechtliche Pflicht.","Die Arbeitspflicht wird durch den Produktwert unwirksam.","Jedes Angebot ohne Geldbetrag ist stets rechtlich vorteilhaft.","Wer 13 ist, kann nur Bargeld als Geschenk erhalten.","Das Angebot ist trotz fehlenden Kaufpreises nicht lediglich rechtlich vorteilhaft.","Eine Gegenleistung zählt nur, wenn sie in Euro angegeben ist."],"answer":[0,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"§ 107 BGB fragt nach rechtlichen Verpflichtungen. Auch eine andere Leistung als Geld kann den rechtlichen Vorteil einschränken.","hint":"Lies genau, welche Leistung die Annahme voraussetzt.","steps":"Lies, welche Folgen die Annahme hat. Suche nach einer Geldzahlung oder einer anderen rechtlichen Pflicht.","example":"Ein Preisnachlass spart Geld. Beim Kauf bleibt trotzdem eine Zahlungspflicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":17,"l":2,"c":2,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Ein Rabatt ersetzt keine Prüfung","scene":"Übungsvariante: Ein 14-Jähriger bestellt ohne Einwilligung einen reduzierten Helm auf Rechnung. Die Rechnung ist offen. Die Eltern haben noch nicht reagiert.","ask":"Welche Aussagen erklären den derzeitigen Stand?","options":["Die offene Rechnung erfüllt § 110 BGB vollständig.","Ein wirksamer Kauf würde auch mit Rabatt eine Zahlungspflicht begründen.","Weil der Preis niedrig ist, gilt die Bestellung als Geschenk.","Ein niedriger Preis macht die Erklärung nichtig.","Die Höhe des Preises klärt, ob die Eltern schon entschieden haben.","Mangels Einwilligung und Zahlung hängt der Vertrag hier noch von der Genehmigung ab."],"answer":[1,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Auch bei einem reduzierten Preis würde ein wirksamer Kauf zur Zahlung verpflichten. In diesem Fall steht die Genehmigung aus und die offene Rechnung erfüllt § 110 BGB noch nicht.","hint":"Trenne Preisvorteil, Zahlungsvorgang und Zustimmung.","steps":"Lies, welche Folgen die Annahme hat. Suche nach einer Geldzahlung oder einer anderen rechtlichen Pflicht.","example":"Ein Preisnachlass spart Geld. Beim Kauf bleibt trotzdem eine Zahlungspflicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":18,"l":2,"c":3,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Eine nachträgliche Zustimmung festhalten","scene":"Übungsvariante: Eine 14-Jährige vereinbart am Montag ohne Einwilligung einen Rechnungskauf. Die Eltern genehmigen denselben Vertrag am Mittwoch. Eine andere gesetzliche Ausnahme ist im Fall nicht einschlägig.","ask":"Was hältst du fest?","options":["Die Rechnung am Montag war bereits eine Genehmigung.","Nachträgliche Zustimmung lässt den Vertrag endgültig unwirksam werden.","Erst ab Mittwoch gilt zwingend ein neuer Vertrag.","Die Zustimmung heißt Einwilligung, weil der Betrag noch nicht gezahlt ist.","Die Zustimmung am Mittwoch ist eine Genehmigung.","Die Genehmigung wirkt im Regelfall auf den Vertragsabschluss zurück."],"answer":[4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"§ 184 BGB ordnet im Regelfall Rückwirkung an. Die nachträgliche Erklärung heißt Genehmigung.","hint":"Verfolge die Reihenfolge vom Abschluss bis zur Zustimmung.","steps":"Markiere den Zeitpunkt des Vertrags und den Stand der Zustimmung. Entscheide erst danach, ob der Fall offen ist.","example":"Die Einwilligung liegt vor dem Vertrag. Eine erst danach erteilte Zustimmung heißt Genehmigung.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":19,"l":2,"c":3,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Den vereinbarten Umfang abgleichen","scene":"Übungsvariante: Eine 15-Jährige darf mit Einwilligung ihrer Eltern ein Schloss bis 40 Euro auf Rechnung kaufen. Sie wählt ein Schloss für 39 Euro auf Rechnung.","ask":"Welche Schritte begründen die Freigabe?","options":["Den Auftrag als Geschenk behandeln.","Den Betrag mit der Grenze abgleichen.","Festhalten, dass die Eltern auch der Rechnungszahlung zugestimmt haben.","Den Auftrag als von der Einwilligung gedeckt beurteilen.","Eine Sofortzahlung allein wegen der Minderjährigkeit verlangen.","Die Grenze anhand des früheren Angebotspreises festlegen."],"answer":[1,2,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Kaufgegenstand, Preis und Zahlungsweise stimmen mit der Einwilligung überein. Die Zahlung kann wie vereinbart erfolgen.","hint":"Vergleiche jeden Teil des Auftrags mit der Zustimmung.","steps":"Markiere den Zeitpunkt des Vertrags und den Stand der Zustimmung. Entscheide erst danach, ob der Fall offen ist.","example":"Die Einwilligung liegt vor dem Vertrag. Eine erst danach erteilte Zustimmung heißt Genehmigung.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":20,"l":2,"c":3,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Von offen zu endgültig unwirksam","scene":"Übungsvariante: Ein 16-Jähriger bestellt ohne vorherige Zustimmung auf Rechnung. Am Morgen ist die Entscheidung der Eltern offen. Am Nachmittag verweigern sie die Genehmigung. Es wurde nichts gezahlt.","ask":"Welche Angaben stimmen im Zeitverlauf?","options":["Die Ablehnung gilt als Genehmigung.","Nach der Verweigerung ist der Vertrag endgültig unwirksam.","Morgens ist der Vertrag schwebend unwirksam.","Morgens war der Kauf bereits aufgrund der Rechnung wirksam.","Die Rechnung ist die erlaubte Zahlung nach § 110 BGB.","Am Nachmittag wird der zuvor offene Vertrag allein durch Zeitablauf wirksam."],"answer":[1,2],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"§ 108 BGB unterscheidet die Lage vor der Entscheidung von der ausdrücklich verweigerten Genehmigung.","hint":"Vergleiche nur das neue Ereignis am Nachmittag.","steps":"Markiere den Zeitpunkt des Vertrags und den Stand der Zustimmung. Entscheide erst danach, ob der Fall offen ist.","example":"Die Einwilligung liegt vor dem Vertrag. Eine erst danach erteilte Zustimmung heißt Genehmigung.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":21,"l":2,"c":4,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Geld von einer anderen Person prüfen","scene":"Übungsvariante: Ein 15-Jähriger zahlt einen Korb vollständig mit Geld, das seine Tante ihm mit Zustimmung der Eltern zur freien Verfügung gegeben hat. Eine ausdrückliche Zustimmung zum Kauf gibt es nicht.","ask":"Welche Angaben stützen die Anwendung von § 110 BGB?","options":["Eine noch ausstehende Rate wäre unerheblich.","Der Kauf muss wirksam sein, weil er in bar erfolgte.","Die Leistung wurde vollständig erbracht.","Das Geld durfte frei eingesetzt werden.","Die Eltern haben der Geldüberlassung durch die Tante zugestimmt.","Geld von Verwandten ist immer ohne Zustimmung zulässig."],"answer":[2,3,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Mit vollständiger Leistung und zulässiger Überlassung stimmen die Voraussetzungen zusammen. Die Tante kann im Fall mit Zustimmung der Eltern Mittel überlassen.","hint":"Prüfe Zahlung, Herkunft und Verwendungszweck getrennt.","steps":"Prüfe zuerst, ob die Leistung vollständig vorliegt. Vergleiche dann Herkunft und erlaubte Verwendung aller eingesetzten Mittel.","example":"Wer nur die erste von zwei Raten zahlt, hat die vereinbarte Leistung noch nicht vollständig erbracht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":22,"l":2,"c":4,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Zwei verschiedene Verwendungszwecke","scene":"Übungsvariante: Eine 14-Jährige hat zwei Umschläge. „Für Fahrradlicht“ enthält 30 Euro, „für Schulhefte“ enthält 20 Euro. Sie bezahlt ein Licht vollständig aus dem ersten Umschlag. Beim zweiten bietet sie das Geld für ein Schloss an. Beides ohne besondere Einwilligung zum Kauf.","ask":"Welche Aussagen prüfen die Zweckbindung richtig?","options":["Das Schulheftgeld darf sie wegen des ersten Kaufs nun frei einsetzen.","Das für Licht vorgesehene Geld kann niemals zweckgerecht eingesetzt werden.","Die Beschriftung darf übergangen werden, wenn beide Geldbeträge ähnlich hoch sind.","Das Geld für das Licht ist für diesen Kauf zweckgerecht eingesetzt.","Das angebotene Geld für das Schloss ist dafür nicht zweckgerecht überlassen.","Beide Umschläge wurden für jedes Fahrradzubehör überlassen."],"answer":[3,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Ein ausdrücklich benannter Zweck kann die Nutzung erlauben oder ausschließen. Beide Käufe werden unabhängig geprüft.","hint":"Lies auf beiden Umschlägen, wofür das Geld überlassen wurde.","steps":"Prüfe zuerst, ob die Leistung vollständig vorliegt. Vergleiche dann Herkunft und erlaubte Verwendung aller eingesetzten Mittel.","example":"Wer nur die erste von zwei Raten zahlt, hat die vereinbarte Leistung noch nicht vollständig erbracht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"id":23,"l":2,"c":4,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Der Zahlungsstand nach drei Raten","scene":"Übungsvariante: Eine 17-Jährige hat einen Anhänger für dreimal 30 Euro ohne Einwilligung gekauft. Alle 90 Euro wurden bereits mit frei verfügbarem Geld ihrer Eltern gezahlt. Keine weitere Leistung ist offen, keine Genehmigung wurde verweigert.","ask":"Welche Einträge passen?","options":["Erst mit der letzten Rate wird die Kundin volljährig.","Der Gesamtpreis ist vollständig gezahlt.","Die ersten 30 Euro allein hätten den ganzen Vertrag sofort wirksam gemacht.","Trotz vollständiger Leistung gilt ein Ratenkauf ohne Einwilligung stets als nichtig.","Unter den Fallbedingungen gilt der Vertrag nach § 110 BGB von Anfang an als wirksam.","§ 110 BGB ist auf Verträge ab 50 Euro grundsätzlich nicht anwendbar."],"answer":[1,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Es kommt auf alle vereinbarten Leistungen und zulässige Mittel an. Mit der vollständigen Erfüllung greift die Rechtsfolge des § 110 BGB.","hint":"Rechne die Raten zusammen und prüfe, ob einer Zahlung noch eine Pflicht gegenübersteht.","steps":"Prüfe zuerst, ob die Leistung vollständig vorliegt. Vergleiche dann Herkunft und erlaubte Verwendung aller eingesetzten Mittel.","example":"Wer nur die erste von zwei Raten zahlt, hat die vereinbarte Leistung noch nicht vollständig erbracht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"]},{"c":0,"title":"Das erste Geschenk dokumentieren","scene":"Übungsvariante: Beim Global-Bike-Aktionstag nehmen Eltern einen geschenkten Kinderhelm für ihr Neugeborenes an. Emma beginnt die Entscheidungshilfe für das Team.","ask":"Welchen Einstieg wählst du für deinen Arbeitsweg?","options":["Trage zwei Belege getrennt ein: Rechtsfähigkeit des Kindes und Erklärung der Eltern.","Lass das Verkaufsteam erklären, wer das Geschenk erhält und wer für das Kind handelt.","Lege für die Entscheidungshilfe getrennte Felder „Beteiligte Person“ und „Vertretung“ an.","Stelle den Fall einer eigenen Bestellung des Kindes gegenüber und erkläre, warum der Unterschied zählt.","Schlage eine kurze Rückfrage an die Eltern vor: „Nehmen Sie das Geschenk für Ihr Kind an?“","Ordne der Kasse und der Dokumentation je einen Schritt zu, damit die Rollen im Vorgang klar bleiben."],"consequences":["Der Unterschied ist in der Akte überprüfbar.","Du erfährst, an welcher Stelle das Team die Rollen verwechselt.","Das Team kann Rechte und Handlungen bei der nächsten Anfrage getrennt erfassen.","Der Vergleich macht die Wirkung der Vertretung sichtbar.","Die Beteiligten bestätigen, in wessen Namen sie handeln.","Zuständigkeiten und Reihenfolge sind für das Team geklärt."],"id":24,"l":3,"type":"story","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","storyIndex":0,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","hint":"Welche Überlegung aus dem letzten Schritt hilft dir hier weiter?","steps":"Entscheide, welchen Beleg, welche Rückmeldung oder welche Vorgabe du jetzt prüfst.","example":"Greife eine Information aus deiner vorigen Entscheidung auf und verwende sie hier.","why":"Am Ende erhältst du eine Rückmeldung zu deiner Entscheidungskette."},{"c":1,"title":"Die Äußerung an der Kasse einordnen","scene":"Übungsvariante: Ein sechsjähriges Kind erklärt an der Kasse, es wolle ein Schloss kaufen, und legt den vollständigen Betrag hin. Niemand handelt für das Kind.","ask":"Wie prüfst du diesen Vorgang im gewählten Arbeitsweg?","options":["Halte Alter, eigenen Kaufwunsch und Zahlung getrennt fest und ordne die Rechtsfolge dem Alter zu.","Erkläre der kassierenden Person, warum das Geld allein den Vertrag nicht wirksam macht.","Ergänze einen Prüfpunkt „unter sieben“ vor der Zahlungsprüfung.","Vergleiche den Fall mit der Annahme des Geschenks durch die Vertreter aus dem ersten Vorgang.","Bitte eine verantwortliche Person am Verkaufsschalter, eine Rückfrage zum nächsten möglichen Schritt mit der Begleitung zu übernehmen.","Vereinbare im Ablauf, dass ein gesetzlicher Vertreter für einen neuen Kauf ausdrücklich handeln kann."],"consequences":["Die Bewertung stützt sich auf die dokumentierte eigene Erklärung.","Das Team kann dem Kind und seiner Begleitung den Punkt verständlich erläutern.","Die Prüfung beginnt künftig mit dem entscheidenden Altersmerkmal.","Der Unterschied zwischen eigener Erklärung und Vertretung bleibt sichtbar.","Die Rolle der Begleitung wird geklärt, ohne die erste Erklärung des Kindes als wirksam zu behandeln.","Das Team kennt eine Möglichkeit, den Vorgang korrekt neu aufzunehmen."],"id":25,"l":3,"type":"story","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","storyIndex":1,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","hint":"Welche Überlegung aus dem letzten Schritt hilft dir hier weiter?","steps":"Entscheide, welchen Beleg, welche Rückmeldung oder welche Vorgabe du jetzt prüfst.","example":"Greife eine Information aus deiner vorigen Entscheidung auf und verwende sie hier.","why":"Am Ende erhältst du eine Rückmeldung zu deiner Entscheidungskette.","branchFrom":24,"branchText":["Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist.","Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist."]},{"c":2,"title":"Geschenk und günstiges Zusatzangebot vergleichen","scene":"Übungsvariante: Eine 14-Jährige bekommt ein Reflektorband ohne Verpflichtungen geschenkt. Ein weiterer Artikel würde 5 Euro kosten.","ask":"Wie erklärst du den Unterschied vor der Entscheidung?","options":["Kennzeichne Geschenk ohne Pflichten und Kauf mit Zahlungspflicht in zwei Zeilen.","Lass die Kundin und das Team noch einmal benennen, ob bei der Annahme eine Gegenleistung erwartet wird.","Miss die Angebote an zwei getrennten Prüfregeln und lasse den Kauf erst nach der nötigen Zustimmung oder Erfüllung prüfen.","Nutze die Zahlungspflicht als Beleg dafür, dass der Zusatzkauf trotz des niedrigen Preises nicht lediglich rechtlich vorteilhaft ist.","Bitte das Team, die Angebote der Kundin mit jeweils einem eigenen Satz zu erklären.","Vergib zwei Vorgangsnummern für die Schenkung und den möglichen Kauf."],"consequences":["Beide Bewertungen lassen sich auf die Bedingungen der Angebote zurückführen.","Die Beteiligten können Geschenk und Zusatzkauf sauber auseinanderhalten.","Der Ablauf verhindert, dass eine Freigabe versehentlich für beide Vorgänge gilt.","Der entscheidende Unterschied wird im Preisgespräch nachvollziehbar.","Die Kundin erhält zwei verständliche Auskünfte statt einer vermischten Zusage.","Dokumentation und Freigabe bleiben für beide Teile getrennt."],"id":26,"l":3,"type":"story","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","storyIndex":2,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","hint":"Welche Überlegung aus dem letzten Schritt hilft dir hier weiter?","steps":"Entscheide, welchen Beleg, welche Rückmeldung oder welche Vorgabe du jetzt prüfst.","example":"Greife eine Information aus deiner vorigen Entscheidung auf und verwende sie hier.","why":"Am Ende erhältst du eine Rückmeldung zu deiner Entscheidungskette.","branchFrom":25,"branchText":["Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist.","Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist."]},{"c":3,"title":"Den Stand einer Rechnung klären","scene":"Übungsvariante: Ein 16-Jähriger hat ohne vorherige Zustimmung Zubehör auf Rechnung bestellt. Es ist nichts bezahlt. Die Eltern haben noch nicht entschieden.","ask":"Welcher Schritt passt zu deiner Prüfung?","options":["Dokumentiere Vertrag, offene Zahlung und fehlende Genehmigung, bevor du die vorläufige Rechtsfolge einträgst.","Formuliere eine kurze Nachricht für die Beteiligten, welche Unterlagen und Entscheidung noch fehlen.","Vermerke den offenen Status und bestimme, wer die spätere Genehmigung oder Verweigerung erfasst.","Vergleiche die offene Rechnung mit einem vorab ausdrücklich erlaubten Rechnungskauf.","Bitte das Verkaufsteam, dem Jugendlichen „Entscheidung steht noch aus“ in verständlichen Worten zu erklären.","Vereinbare, wann der Vorgang erneut aufgerufen und welcher Inhalt geprüft wird."],"consequences":["Die Akte zeigt klar, worauf der vorläufige Status beruht.","Die Eltern können sich zum konkreten Vertrag äußern.","Der Vorgang kann geprüft werden, bevor er als wirksam behandelt wird.","Die unterschiedliche Rolle der Einwilligung wird sichtbar.","Die Kommunikation stellt den Zwischenstand dar, ohne eine Entscheidung vorwegzunehmen.","Die offene Entscheidung bleibt im dokumentierten Ablauf sichtbar."],"id":27,"l":3,"type":"story","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","storyIndex":3,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","hint":"Welche Überlegung aus dem letzten Schritt hilft dir hier weiter?","steps":"Entscheide, welchen Beleg, welche Rückmeldung oder welche Vorgabe du jetzt prüfst.","example":"Greife eine Information aus deiner vorigen Entscheidung auf und verwende sie hier.","why":"Am Ende erhältst du eine Rückmeldung zu deiner Entscheidungskette.","branchFrom":26,"branchText":["Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist.","Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist."]},{"c":4,"title":"Überlassung der Mittel und Raten prüfen","scene":"Übungsvariante: Bei einem anderen Vorgang hat eine 17-Jährige alle drei Raten aus frei verfügbarem Geld ihrer Eltern beglichen. Es gibt keine weiteren Pflichten. Keine Genehmigung wurde vorher verweigert.","ask":"Wie leitest du aus den Angaben deine Empfehlung ab?","options":["Gleiche die vereinbarten Raten mit den Zahlungen ab und belege zusätzlich die erlaubte Herkunft des Geldes.","Besprich mit der Verwaltung, welche Auskunft zu Geldherkunft und offenem Rest benötigt wird.","Ergänze für Ratengeschäfte einen Abschlussprüfpunkt für letzte Rate und zulässige Mittel.","Schreibe einen passenden Gegenfall auf: Eine Rate ist offen oder Geld ist für einen fremden Zweck gebunden.","Lass eine Kollegin in eigenen Worten erklären, wann sich der Stand mit der letzten Rate ändert.","Ordne der Verwaltung eine Kontrolle der Zahlungsliste zu und notiere, welche Angabe zur Herkunft im Fallblatt stehen muss."],"consequences":["Zahlung und Mittelherkunft tragen das Ergebnis gemeinsam.","Das Team sammelt die fehlenden Informationen gezielt und verständlich.","Der Ablauf enthält die Bedingungen für eine Freigabe des Vorgangs.","Der Vergleich zeigt, warum vollständiges Zahlen allein nicht in jedem Fall ausreicht.","Du erkennst, ob die rechtliche Begründung im Team angekommen ist.","Zuständigkeit und erforderliche Dokumentation sind festgelegt."],"id":28,"l":3,"type":"story","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","storyIndex":4,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","hint":"Welche Überlegung aus dem letzten Schritt hilft dir hier weiter?","steps":"Entscheide, welchen Beleg, welche Rückmeldung oder welche Vorgabe du jetzt prüfst.","example":"Greife eine Information aus deiner vorigen Entscheidung auf und verwende sie hier.","why":"Am Ende erhältst du eine Rückmeldung zu deiner Entscheidungskette.","branchFrom":27,"branchText":["Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist.","Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist."]},{"c":3,"title":"Eine Empfehlung in der Entscheidungshilfe geben","scene":"Übungsvariante: Die Eltern des Rechnungskäufers haben die Genehmigung inzwischen ausdrücklich verweigert. Jan will die Kurzfassung für die nächste Schicht nutzen.","ask":"Wie schließt du deinen Arbeitsweg ab?","options":["Stelle die dokumentierte Ablehnung dem früher offenen Status gegenüber und trage die endgültige Unwirksamkeit ein.","Erkläre der nächsten Schicht, wie sie der Kundschaft den Wechsel von „offen“ zu „verweigert“ mitteilt.","Halte die Verweigerung als Schlussereignis fest und beschreibe, wer den Vorgang im System entsprechend abschließt.","Verknüpfe den Schlussvermerk zur Rechnung mit den anders begründeten Entscheidungen zu Geschenk und vollständiger Ratenzahlung.","Lass eine Kollegin die Kurzfassung an einem der Fälle erklären und bitte um eine Rückmeldung zu unklaren Begriffen.","Ergänze ein Prüffeld für künftige Fälle: Zustimmung offen, erteilt oder verweigert sowie Datum und zuständige Person."],"consequences":["Die Entscheidung lässt sich aus dem bekannten Zeitverlauf erklären.","Die Schicht kann den aktuellen Stand klar und respektvoll weitergeben.","Der Ablauf stellt sicher, dass der Auftrag nicht wie genehmigt weiterläuft.","Die Kurzfassung zeigt, wie sich die Bewertungen aus unterschiedlichen Belegen ergeben.","Du prüfst, ob die Entscheidungshilfe im Verkaufsgespräch verstanden wird.","Das Team hat eine eindeutige Grundlage für die nächsten Vorgänge."],"id":29,"l":3,"type":"story","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","storyIndex":5,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","hint":"Welche Überlegung aus dem letzten Schritt hilft dir hier weiter?","steps":"Entscheide, welchen Beleg, welche Rückmeldung oder welche Vorgabe du jetzt prüfst.","example":"Greife eine Information aus deiner vorigen Entscheidung auf und verwende sie hier.","why":"Am Ende erhältst du eine Rückmeldung zu deiner Entscheidungskette.","branchFrom":28,"branchText":["Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist.","Beziehe die Angaben ein, die du gerade geprüft hast.","Berücksichtige die Rückmeldung oder Sichtweise, die du aufgenommen hast.","Prüfe, welche Vorgabe oder Grenze aus der vorigen Entscheidung jetzt wichtig ist."]},{"id":30,"l":1,"c":0,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Wer nimmt das Geschenk an?","scene":"Übungsvariante: Die Eltern nehmen einen Kinderhelm für ihr zwei Monate altes Kind an.","ask":"Wer handelt in dieser Situation?","options":["Die Eltern handeln für das Kind.","Die Eltern handeln hier nur für sich.","Der Helm kann dem Kind erst ab sieben geschenkt werden.","Der Helm kann nur von einem Erwachsenen besessen werden.","Das Kind gibt selbst eine Erklärung ab.","Die Übergabe macht das Baby voll geschäftsfähig."],"answer":[0],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Eltern geben die Erklärung für ihr Kind ab. Das Kind kann Eigentum erwerben, obwohl es noch keinen Vertrag selbst schließen kann.","hint":"Achte auf die Formulierung „für ihr Kind“.","steps":"Unterstreiche die Person, die ein Recht erhalten kann. Prüfe getrennt, wer die Erklärung abgibt.","example":"Bei einem Geschenk kann das Kind Eigentümer sein, während die gesetzlichen Vertreter die Annahme erklären.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":0,"reserveNo":1},{"id":31,"l":1,"c":0,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Zwei Aussagen zur Geschenkempfängerin","scene":"Übungsvariante: Ein sechs Wochen altes Kind bekommt einen Fahrradanhänger geschenkt. Die gesetzlichen Vertreter nehmen das Geschenk für das Kind an.","ask":"Welche Aussagen kann Emma im Fallblatt festhalten?","options":["Das Kind kann nun weitere Geschenke allein wirksam annehmen.","Das Kind ist bereits rechtsfähig.","Das Geschenk kann nicht dem Kind gehören.","Die gesetzlichen Vertreter nehmen das Geschenk an seiner Stelle an.","Das Kind ist wegen des Geschenks beschränkt geschäftsfähig.","Rechtsfähigkeit beginnt erst mit der ersten eigenen Unterschrift."],"answer":[1,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Der Anhänger kann dem Kind gehören. Die Annahme durch seine Vertreter setzt keine eigene geschäftliche Entscheidung des Kindes voraus.","hint":"Prüfe getrennt, wer Rechte hat und wer die Erklärung abgibt.","steps":"Unterstreiche die Person, die ein Recht erhalten kann. Prüfe getrennt, wer die Erklärung abgibt.","example":"Bei einem Geschenk kann das Kind Eigentümer sein, während die gesetzlichen Vertreter die Annahme erklären.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":0,"reserveNo":2},{"id":32,"l":1,"c":0,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Die passende Erklärung auswählen","scene":"Übungsvariante: Ein Mitarbeiter sagt: „Ein Kind, das noch keinen Kauf selbst abschließen kann, kann auch kein Eigentümer sein.“","ask":"Welche Erklärung antwortet richtig?","options":["Die Rechtsfähigkeit endet, solange die Eltern vertreten.","Kaufentscheidung und Eigentümerstellung sind immer dasselbe.","Bargeld ersetzt für Kinder die Rechtsfähigkeit.","Das Kind muss Eigentum grundsätzlich bis 18 abgeben.","Wer etwas besitzt, ist im Regelfall volljährig.","Das Kind kann Eigentümer sein, obwohl es einen Kauf nicht selbst wirksam abschließen kann."],"answer":[5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Rechtsfähigkeit betrifft die Frage, ob jemand Rechte haben kann. Geschäftsfähigkeit betrifft eigene rechtliche Erklärungen.","hint":"Prüfe, ob die Aussage über Eigentum aus der Aussage über den Kauf folgt.","steps":"Unterstreiche die Person, die ein Recht erhalten kann. Prüfe getrennt, wer die Erklärung abgibt.","example":"Bei einem Geschenk kann das Kind Eigentümer sein, während die gesetzlichen Vertreter die Annahme erklären.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":1,"reserveNo":1},{"id":33,"l":1,"c":0,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Zwei Spalten richtig ausfüllen","scene":"Übungsvariante: In einer Lernkarte steht links „einen geschenkten Gegenstand als Eigentümer haben“, rechts „einen Vertrag selbst wirksam schließen“.","ask":"Welcher Eintrag passt wohin?","options":["Links gehört nur die Volljährigkeit hin.","Links geht es um die Zustimmung zur Rechnung.","Rechts geht es ausschließlich um Bargeld.","Links gehört die Rechtsfähigkeit hin.","Rechts gehört die Geschäftsfähigkeit hin.","Rechts und links bedeuten beides Geschäftsfähigkeit."],"answer":[3,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Beide Begriffe stellen unterschiedliche Fragen. Rechtsfähigkeit macht die eigene Erklärung noch nicht wirksam.","hint":"Lies jeweils das Verb: etwas haben oder etwas selbst wirksam vereinbaren?","steps":"Unterstreiche die Person, die ein Recht erhalten kann. Prüfe getrennt, wer die Erklärung abgibt.","example":"Bei einem Geschenk kann das Kind Eigentümer sein, während die gesetzlichen Vertreter die Annahme erklären.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":1,"reserveNo":2},{"id":34,"l":1,"c":1,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Der siebte Geburtstag","scene":"Übungsvariante: In der Übersicht wird der heutige siebte Geburtstag einer Kundin mit dem gestrigen Alter verglichen.","ask":"Welche Zuordnungen sind richtig?","options":["Gestern war sie wegen ihres Alters geschäftsunfähig.","Heute bleibt sie bis zum achten Geburtstag geschäftsunfähig.","Heute ist sie beschränkt geschäftsfähig.","Gestern war sie noch nicht rechtsfähig.","Die Altersstufe hängt vom Betrag des Einkaufs ab.","Seit heute ist sie volljährig."],"answer":[0,2],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Mit dem siebten Geburtstag beginnt die beschränkte Geschäftsfähigkeit. Rechte kann das Kind schon vorher haben.","hint":"Prüfe, welches Lebensjahr die Kundin heute vollendet.","steps":"Ordne zuerst das Alter am Tag des Geschäfts ein. Prüfe danach, von wem die Erklärung stammt.","example":"Das Alter einer Person wird am Tag der eigenen Erklärung geprüft. Ein späterer Geburtstag ändert den damaligen Stand nicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":2,"reserveNo":1},{"id":35,"l":1,"c":1,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Drei Kundenzettel zuordnen","scene":"Übungsvariante: Emma erhält Kundenzettel mit den Altersangaben 4, 17 und 19. Es gibt keine weiteren Einschränkungen.","ask":"Welche Zeilen kann sie übernehmen?","options":["19: bis zum nächsten Geburtstag beschränkt geschäftsfähig.","19: im Regelfall voll geschäftsfähig.","4: wegen der Rechtsfähigkeit voll geschäftsfähig.","17: im Regelfall voll geschäftsfähig.","17: beschränkt geschäftsfähig.","4: geschäftsunfähig."],"answer":[1,4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Das Alter entscheidet hier über die drei Stufen. Die Rechtsfähigkeit besteht bei allen drei Personen.","hint":"Trenne die Grenzen „unter 7“, „7 bis 17“ und „ab 18“.","steps":"Ordne zuerst das Alter am Tag des Geschäfts ein. Prüfe danach, von wem die Erklärung stammt.","example":"Das Alter einer Person wird am Tag der eigenen Erklärung geprüft. Ein späterer Geburtstag ändert den damaligen Stand nicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":2,"reserveNo":2},{"id":36,"l":1,"c":1,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Sechs Jahre und zwei Euro","scene":"Übungsvariante: Ein sechsjähriges Kind legt für eine Ventilkappe zwei Euro auf den Tisch. Es handelt allein.","ask":"Was entscheidet für die eigene Erklärung des Kindes?","options":["Das Kind wird durch den Kauf beschränkt geschäftsfähig.","Das Kind ist noch keine sieben Jahre alt.","Zwei Euro liegen unter einer allgemeinen Freigrenze.","Der Verkäufer entscheidet mit der Quittung über das Alter.","Die Erklärung ist wegen Geschäftsunfähigkeit nichtig.","Zahlung macht die Erklärung wirksam."],"answer":[1,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Auch bei einem kleinen Betrag bleibt die eigene Erklärung eines geschäftsunfähigen Kindes nichtig.","hint":"Der Preis ersetzt die Prüfung der Altersstufe nicht.","steps":"Ordne zuerst das Alter am Tag des Geschäfts ein. Prüfe danach, von wem die Erklärung stammt.","example":"Das Alter einer Person wird am Tag der eigenen Erklärung geprüft. Ein späterer Geburtstag ändert den damaligen Stand nicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":3,"reserveNo":1},{"id":37,"l":1,"c":1,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Wer könnte wirksam handeln?","scene":"Übungsvariante: Ein 4-Jähriger will eine Trinkflasche selbst kaufen. Seine gesetzliche Vertreterin kommt dazu und möchte sie für ihn kaufen.","ask":"Welche beiden Aussagen passen?","options":["Das Kind ist nicht rechtsfähig.","Die Vertreterin darf nur bei einem Geschenk handeln.","Die gesetzliche Vertreterin kann selbst für das Kind handeln.","Die Anwesenheit der Vertreterin macht das Kind voll geschäftsfähig.","Die eigene Erklärung des Kindes ist nichtig.","Die erste Erklärung wird allein durch Bezahlung wirksam."],"answer":[2,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die erste Erklärung stammt von einem geschäftsunfähigen Kind. Die Vertreterin kann an seiner Stelle eine eigene Erklärung abgeben.","hint":"Unterscheide die Erklärung des Kindes von der späteren Erklärung der Erwachsenen.","steps":"Ordne zuerst das Alter am Tag des Geschäfts ein. Prüfe danach, von wem die Erklärung stammt.","example":"Das Alter einer Person wird am Tag der eigenen Erklärung geprüft. Ein späterer Geburtstag ändert den damaligen Stand nicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":3,"reserveNo":2},{"id":38,"l":1,"c":2,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Ein Geschenk ohne Gegenleistung","scene":"Übungsvariante: Einer 12-Jährigen wird ein Fahrradkorb ohne Rückgabe- oder Zahlungspflicht geschenkt.","ask":"Welche Aussage erklärt die Annahme?","options":["Der Preis des Korbs macht die Kundin voll geschäftsfähig.","Jedes Geschenk muss bis zum 18. Geburtstag abgelehnt werden.","Für diese Annahme ist keine Einwilligung nötig.","Ein teurer Korb ist immer ein rechtlicher Nachteil.","Der Korb zählt erst nach Zahlung als Geschenk.","Die Annahme ist nur nach § 110 BGB möglich."],"answer":[2],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Kundin erhält einen Vorteil und übernimmt keine Pflicht. In diesem Fall erlaubt § 107 BGB die eigene Annahme.","hint":"Prüfe Angebot und Gegenleistung getrennt.","steps":"Lies, welche Folgen die Annahme hat. Suche nach einer Geldzahlung oder einer anderen rechtlichen Pflicht.","example":"Ein Preisnachlass spart Geld. Beim Kauf bleibt trotzdem eine Zahlungspflicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":4,"reserveNo":1},{"id":39,"l":1,"c":2,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Geschenk oder Verpflichtung?","scene":"Übungsvariante: Ein 16-Jähriger hat die Wahl zwischen einer geschenkten Pumpe ohne Pflichten und einem Zubehörpaket, das er für zehn Euro annehmen könnte.","ask":"Welche beiden Aussagen trennen die Fälle richtig?","options":["Er muss die Eltern allein wegen seines Alters um Erlaubnis für die Pumpe bitten.","Die Pumpe braucht denselben Prüfschritt nach § 110 BGB wie ein Kauf.","Beide Gegenstände sind Geschenke, weil sie Zubehör sind.","Der geringe Paketpreis macht den Kauf lediglich rechtlich vorteilhaft.","Die Annahme des Pakets würde eine Zahlungspflicht begründen.","Die Pumpe ohne Pflichten kann er selbst annehmen."],"answer":[4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Bei der Pumpe entsteht keine Pflicht. Beim Paket kommt mit der Annahme eine Zahlungsverpflichtung hinzu.","hint":"Suche in beiden Angeboten nach einer Gegenleistung.","steps":"Lies, welche Folgen die Annahme hat. Suche nach einer Geldzahlung oder einer anderen rechtlichen Pflicht.","example":"Ein Preisnachlass spart Geld. Beim Kauf bleibt trotzdem eine Zahlungspflicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":4,"reserveNo":2},{"id":40,"l":1,"c":2,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Ein Euro für ein Schloss","scene":"Übungsvariante: Eine 14-Jährige kann ein gebrauchtes Schloss für einen Euro kaufen.","ask":"Wodurch unterscheidet sich das Angebot von einer Schenkung ohne Pflichten?","options":["Die Form des Schlüssels bestimmt die rechtliche Wirkung.","Die Rechnung wird mit ihrem Geburtstag wirksam.","Das Schloss kostet weniger als ein neues.","Der Anbieter muss beim Verkauf immer ein neues Schloss mitgeben.","Bei einem wirksamen Kauf wäre der vereinbarte Euro zu zahlen.","Sie darf erst ab 18 Eigentum an einem Schloss haben."],"answer":[4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Auch ein symbolischer Preis ist eine Gegenleistung. Daher unterscheidet sich der angebotene Kauf von einer Schenkung ohne Pflichten.","hint":"Achte auf das Wort „für“ vor dem Preis.","steps":"Lies, welche Folgen die Annahme hat. Suche nach einer Geldzahlung oder einer anderen rechtlichen Pflicht.","example":"Ein Preisnachlass spart Geld. Beim Kauf bleibt trotzdem eine Zahlungspflicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":5,"reserveNo":1},{"id":41,"l":1,"c":2,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Rabatt und Rechtsfolge prüfen","scene":"Übungsvariante: Ein Zubehörset ist um 80 % reduziert. Der Verkäufer sagt, es sei daher nur rechtlich vorteilhaft, wenn eine 15-Jährige es auf Rechnung bestellt.","ask":"Welche Korrekturen sind richtig?","options":["Die Höhe des Rabatts beseitigt die Zahlungspflicht nicht.","Der Einkauf wird durch die Einigung über den Preis immer nichtig.","Erst eine Zahlung macht die Kundin rechtsfähig.","Ein niedriger Preis ersetzt automatisch die Zustimmung der Eltern.","Eine Rechnung kann eine Zahlungspflicht auslösen.","Bei mehr als 50 % Rabatt gilt ein Kauf als Geschenk."],"answer":[0,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die beschränkte Geschäftsfähigkeit muss unabhängig vom Preisvorteil geprüft werden. § 107 BGB fragt nach rechtlichen Nachteilen.","hint":"Vergleiche den tatsächlichen Preisvorteil mit der übernommenen Verpflichtung.","steps":"Lies, welche Folgen die Annahme hat. Suche nach einer Geldzahlung oder einer anderen rechtlichen Pflicht.","example":"Ein Preisnachlass spart Geld. Beim Kauf bleibt trotzdem eine Zahlungspflicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":5,"reserveNo":2},{"id":42,"l":1,"c":3,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Eine Zustimmung vor dem Kauf","scene":"Übungsvariante: Die Eltern sagen vor dem Kauf ausdrücklich zu, dass ihr 15-jähriges Kind bei Global Bike eine Tasche für 25 Euro kaufen darf.","ask":"Welcher Begriff bezeichnet diese Zustimmung?","options":["Schwebende Unwirksamkeit.","Nichtigkeit.","Genehmigung.","Mängelrüge.","Einwilligung.","Rechnung."],"answer":[4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Zustimmung liegt schon vor dem Geschäft und heißt Einwilligung.","hint":"Markiere den Zeitpunkt im ersten Satz.","steps":"Markiere den Zeitpunkt des Vertrags und den Stand der Zustimmung. Entscheide erst danach, ob der Fall offen ist.","example":"Die Einwilligung liegt vor dem Vertrag. Eine erst danach erteilte Zustimmung heißt Genehmigung.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":6,"reserveNo":1},{"id":43,"l":1,"c":3,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Die Zeitstempel vergleichen","scene":"Übungsvariante: Ein Fallblatt dokumentiert Mittwoch 10 Uhr das Angebot, 11 Uhr den Vertrag und 14 Uhr die Zustimmung der Eltern.","ask":"Welche Aussagen passen zu diesem Zeitablauf?","options":["Die Genehmigung wird nach dem Vertrag erteilt.","Die Genehmigung erfordert immer eine Barzahlung am selben Tag.","Die Zustimmung um 14 Uhr ist eine Einwilligung, weil die Rechnung noch offen ist.","Die Anordnung der Zeiten ist für die Begriffe ohne Bedeutung.","Die Zustimmung um 14 Uhr heißt Genehmigung.","Das Angebot um 10 Uhr ist die Zustimmung der Eltern."],"answer":[0,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Für die Bezeichnung kommt es darauf an, ob die Zustimmung vor oder nach dem Vertrag kommt. Die Rechnung bestimmt den Begriff nicht.","hint":"Vergleiche 11 Uhr mit 14 Uhr und ordne erst dann zu.","steps":"Markiere den Zeitpunkt des Vertrags und den Stand der Zustimmung. Entscheide erst danach, ob der Fall offen ist.","example":"Die Einwilligung liegt vor dem Vertrag. Eine erst danach erteilte Zustimmung heißt Genehmigung.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":6,"reserveNo":2},{"id":44,"l":1,"c":3,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Eine klare Grenze einhalten","scene":"Übungsvariante: Eine 16-Jährige darf mit ausdrücklicher Zustimmung ihrer Eltern ein bestimmtes Schloss auf Rechnung für höchstens 35 Euro bestellen. Sie bestellt dieses Modell für 32 Euro.","ask":"Welche Aussage stimmt?","options":["Die Zustimmung wurde erst nach der Bestellung erteilt.","Rechnungskäufe Minderjähriger sind stets unwirksam.","Das Schloss wird durch die Zustimmung zum Geschenk.","Die 32 Euro müssen bereits bar gezahlt sein.","Die Kundin ist erst bei Lieferung beschränkt geschäftsfähig.","Der Kauf ist von der Einwilligung gedeckt."],"answer":[5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Modell, Preis und Zahlungsweise entsprechen dem Umfang der vorherigen Zustimmung.","hint":"Gleiche alle drei Bedingungen mit der Bestellung ab.","steps":"Markiere den Zeitpunkt des Vertrags und den Stand der Zustimmung. Entscheide erst danach, ob der Fall offen ist.","example":"Die Einwilligung liegt vor dem Vertrag. Eine erst danach erteilte Zustimmung heißt Genehmigung.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":7,"reserveNo":1},{"id":45,"l":1,"c":3,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Bei der Einwilligung genau lesen","scene":"Übungsvariante: Ein 15-Jähriger darf eine Pumpe auf Rechnung erwerben. Ohne weitere Zustimmung schließt er zusätzlich einen eigenen Kaufvertrag über ein Werkzeug auf Rechnung.","ask":"Welche Aussagen sind begründet?","options":["Die Zustimmung deckt den Kauf der Pumpe ab.","Der Werkzeugkauf ist bereits durch vollständige Zahlung wirksam.","Die Zustimmung zur Pumpe gilt pauschal für jedes Zubehör.","Für den zusätzlich vereinbarten Werkzeugkauf fehlt die beschriebene Einwilligung.","Die Rechnung erlaubt es dem Kunden, die Zustimmung selbst zu ersetzen.","Der Kauf der Pumpe wird wegen des Werkzeugs automatisch nichtig."],"answer":[0,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Reichweite der Zustimmung zählt. Prüft die Vereinbarungen im Fall getrennt, da sie eigenständig zustande kommen.","hint":"Achte auf das Wort „zusätzlich“. Die Eltern erlauben einen konkreten Kauf.","steps":"Markiere den Zeitpunkt des Vertrags und den Stand der Zustimmung. Entscheide erst danach, ob der Fall offen ist.","example":"Die Einwilligung liegt vor dem Vertrag. Eine erst danach erteilte Zustimmung heißt Genehmigung.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":7,"reserveNo":2},{"id":46,"l":1,"c":3,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Die Ablehnung erfassen","scene":"Übungsvariante: Eine 16-Jährige bestellt ohne Einwilligung einen Korb auf Rechnung. Es wurde nichts gezahlt. Ihre gesetzlichen Vertreter verweigern die Genehmigung.","ask":"Welcher Stand gehört ins Fallblatt?","options":["Die Kundin wird durch die Ablehnung geschäftsunfähig.","Die Ablehnung ändert nur, wann das Geschäft in Rechnung gestellt wird.","Der Vertrag bleibt ungeachtet der Ablehnung schwebend unwirksam.","Die Druckfreigabe der Rechnung ersetzt die Genehmigung.","Der Vertrag ist endgültig unwirksam.","Der Vertrag gilt wegen des Preises als teilwirksam."],"answer":[4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Ohne Einwilligung und ohne andere Grundlage hängt der Fall von der Genehmigung ab. Mit ihrer Verweigerung besteht keine schwebende Lage mehr.","hint":"Achte darauf, ob eine Entscheidung getroffen wurde.","steps":"Markiere den Zeitpunkt des Vertrags und den Stand der Zustimmung. Entscheide erst danach, ob der Fall offen ist.","example":"Die Einwilligung liegt vor dem Vertrag. Eine erst danach erteilte Zustimmung heißt Genehmigung.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":8,"reserveNo":1},{"id":47,"l":1,"c":3,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Zwei Bestellungen auseinanderhalten","scene":"Übungsvariante: Zwei 15-Jährige bestellen jeweils ohne Zustimmung und ohne Zahlung auf Rechnung. Bei K fragen die Eltern noch nach Unterlagen. Bei L verweigern sie die Genehmigung.","ask":"Welche Zeilen sind richtig?","options":["K: Der Auftrag ist wegen der Rückfrage wirksam.","Beide sind als lediglich rechtlich vorteilhaft einzuordnen.","L: Die Ablehnung gilt als Einwilligung.","Beide Bestellungen werden durch Ausstellen der Rechnung wirksam.","L: Genehmigung ausdrücklich verweigert, also endgültig unwirksam.","K: Genehmigung steht aus, also schwebend unwirksam."],"answer":[4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Zahlungspflicht braucht hier eine Wirkungsvoraussetzung. K bleibt vorerst offen; bei L ist die Genehmigung verweigert.","hint":"Prüfe für jeden Auftrag den Entscheidungsstand der gesetzlichen Vertreter.","steps":"Markiere den Zeitpunkt des Vertrags und den Stand der Zustimmung. Entscheide erst danach, ob der Fall offen ist.","example":"Die Einwilligung liegt vor dem Vertrag. Eine erst danach erteilte Zustimmung heißt Genehmigung.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":8,"reserveNo":2},{"id":48,"l":1,"c":4,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Nur eine von zwei Zahlungen","scene":"Übungsvariante: Eine 15-Jährige vereinbart ohne Zustimmung zwei Zahlungen und hat bisher nur die erste aus frei verfügbarem Taschengeld gezahlt.","ask":"Welches Merkmal fehlt für § 110 BGB?","options":["Die erste Rate hätte zu Hause übergeben werden müssen.","Sie ist noch nicht rechtsfähig.","Die Ware ist wegen der Zahl der Raten ein Geschenk.","Sie hätte immer mit Karte bezahlen müssen.","Die vereinbarte Leistung ist noch nicht vollständig erbracht.","Ihr Taschengeld muss zwingend von einer Bank stammen."],"answer":[4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Ein Teilbetrag erfüllt die Zahlungspflicht noch nicht. Frei verfügbares Geld allein genügt nicht.","hint":"Vergleiche gezahlte und vereinbarte Raten.","steps":"Prüfe zuerst, ob die Leistung vollständig vorliegt. Vergleiche dann Herkunft und erlaubte Verwendung aller eingesetzten Mittel.","example":"Wer nur die erste von zwei Raten zahlt, hat die vereinbarte Leistung noch nicht vollständig erbracht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":9,"reserveNo":1},{"id":49,"l":1,"c":4,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Bargeld aus zwei Quellen","scene":"Übungsvariante: Ein 16-Jähriger will ohne Einwilligung eine Tasche kaufen. Einen Teil des Geldes gab ihm sein Vater zur freien Verfügung. Den Rest gab ihm jemand ohne Wissen oder Zustimmung seiner gesetzlichen Vertreter.","ask":"Was ist bei vollständiger Zahlung zu prüfen?","options":["Jedes Geld von Dritten ist automatisch ein gesetzlich zugelassenes Mittel.","Weil beide Beträge bar sind, ist die Herkunft bedeutungslos.","Die Voraussetzung zur zulässigen Herkunft ist für den zweiten Teil im Fall nicht erfüllt.","Vollständige Zahlung reicht immer aus.","Erst ab 18 darf Geld zur freien Verfügung überlassen werden.","Der erste Teil ist ausdrücklich zur freien Verfügung überlassen."],"answer":[2,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Für Geld von Dritten kommt es auf die Zustimmung der gesetzlichen Vertreter an. Zwei Teilbeträge können unterschiedliche Voraussetzungen erfüllen.","hint":"Prüfe jede Geldquelle getrennt.","steps":"Prüfe zuerst, ob die Leistung vollständig vorliegt. Vergleiche dann Herkunft und erlaubte Verwendung aller eingesetzten Mittel.","example":"Wer nur die erste von zwei Raten zahlt, hat die vereinbarte Leistung noch nicht vollständig erbracht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":9,"reserveNo":2},{"id":50,"l":1,"c":4,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Bastelgeld am Fahrradregal","scene":"Übungsvariante: Einer 12-Jährigen wird Geld ausschließlich für ein Bastelprojekt überlassen. Im Fahrradladen bezahlt sie ohne weitere Zustimmung eine Klingel vollständig damit.","ask":"Warum genügt die Zahlung hier nicht?","options":["Bei Barzahlung gilt das Geld zwangsläufig als frei verfügbar.","Die Zweckbindung ist nur bei Kartenzahlung wirksam.","Die Zahlung macht eine Genehmigung generell unmöglich.","Die Klingel kostet Geld, auch wenn § 110 BGB jede Zahlung zulässt.","Wer zwölf ist, kann nie ein Geschäft nach § 110 BGB schließen.","Das Geld war nicht für die Klingel und nicht zur freien Verfügung überlassen."],"answer":[5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Vollständig gezahlt bedeutet nur, dass kein Betrag offenbleibt. Die Mittel müssen zusätzlich zulässig überlassen sein.","hint":"Lies noch einmal das Wort „ausschließlich“.","steps":"Prüfe zuerst, ob die Leistung vollständig vorliegt. Vergleiche dann Herkunft und erlaubte Verwendung aller eingesetzten Mittel.","example":"Wer nur die erste von zwei Raten zahlt, hat die vereinbarte Leistung noch nicht vollständig erbracht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":10,"reserveNo":1},{"id":51,"l":1,"c":4,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Zweckgebunden und frei unterscheiden","scene":"Übungsvariante: Ein 14-Jähriger zahlt für einen Korb 20 Euro: 15 Euro sind frei verfügbar, fünf Euro stammen aus Geld, das ausschließlich für ein Schulheft bestimmt ist. Eine Zustimmung zum Kauf fehlt.","ask":"Welche Aussagen sind richtig?","options":["Die fünf Euro sind für diesen Kauf nicht freigegeben.","Die Zweckbindung gilt nur, wenn sie auf der Rechnung steht.","Die vollständige Zahlung mit beiden Beträgen erfüllt § 110 BGB hier nicht.","Der größere frei verfügbare Teil genügt automatisch für den gesamten Kauf.","Ein Korb ist ein Geschenk, sobald er vollständig bezahlt wird.","Geld unter fünf Euro verliert seine Zweckbindung."],"answer":[0,2],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die vertragsmäßige Leistung muss vollständig mit zulässig überlassenen Mitteln erbracht werden. Der zweckfremde Anteil verhindert das hier.","hint":"Zerlege den Betrag und prüfe beide Teile einzeln.","steps":"Prüfe zuerst, ob die Leistung vollständig vorliegt. Vergleiche dann Herkunft und erlaubte Verwendung aller eingesetzten Mittel.","example":"Wer nur die erste von zwei Raten zahlt, hat die vereinbarte Leistung noch nicht vollständig erbracht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":10,"reserveNo":2},{"id":52,"l":1,"c":4,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Die letzte Rate ist offen","scene":"Übungsvariante: Ein 15-Jähriger hat zwei von drei Raten für Zubehör aus frei verfügbarem Taschengeld bezahlt. Eine Genehmigung fehlt und wurde nicht verweigert.","ask":"Welche Aussagen sind begründet?","options":["Die letzte Rate ist ein Geschenk des Verkäufers.","Die Ratenzahl ändert das Alter des Käufers.","Die Eltern können nach diesem Zwischenstand nie genehmigen.","Bis zur vollständigen Erfüllung reicht § 110 BGB hier nicht aus.","Die dritte Rate ist für die Frage nach vollständiger Leistung noch offen.","Die zwei gezahlten Raten machen den Vertrag sofort vollständig wirksam."],"answer":[3,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die zweckgerechte Herkunft der Mittel ist nur eine Voraussetzung. Solange eine Rate aussteht, ist die vollständige Leistung nicht erbracht.","hint":"Zähle die Raten, die schon bezahlt sind, und die, die noch fehlen.","steps":"Prüfe zuerst, ob die Leistung vollständig vorliegt. Vergleiche dann Herkunft und erlaubte Verwendung aller eingesetzten Mittel.","example":"Wer nur die erste von zwei Raten zahlt, hat die vereinbarte Leistung noch nicht vollständig erbracht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":11,"reserveNo":1},{"id":53,"l":1,"c":4,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Zwei Ratenfälle vergleichen","scene":"Übungsvariante: Zwei 16-Jährige kaufen ohne Einwilligung, sonst gleiche Bedingungen. Für P sind alle Beträge mit frei verfügbarem Geld der Eltern beglichen. Für Q fehlt eine Rate. Eine Genehmigung wurde in beiden Fällen weder erteilt noch verweigert.","ask":"Welche Zuordnung ist richtig?","options":["Beide gelten mit der ersten Rate als vollständig bezahlt.","Bei Q reicht die bisherige Zahlung für § 110 BGB nicht.","P wird erst am 18. Geburtstag wirksam.","Q erfüllt § 110 BGB wegen des freien Taschengelds schon jetzt.","P erfüllt unter den genannten Bedingungen § 110 BGB.","Beide Verkäufe sind allein wegen der Ratenform nichtig."],"answer":[1,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Zahlungsart allein entscheidet nicht. Ausschlaggebend ist, ob die Leistung vollständig mit zulässigen Mitteln erbracht wurde.","hint":"Vergleiche die Fälle an derselben Prüffrage: Ist noch etwas offen?","steps":"Prüfe zuerst, ob die Leistung vollständig vorliegt. Vergleiche dann Herkunft und erlaubte Verwendung aller eingesetzten Mittel.","example":"Wer nur die erste von zwei Raten zahlt, hat die vereinbarte Leistung noch nicht vollständig erbracht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":11,"reserveNo":2},{"id":54,"l":2,"c":0,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Einen Fehler im Gespräch erkennen","scene":"Übungsvariante: Ein Kunde sagt am Telefon, ein geschenktes Rad müsse bis zum siebten Geburtstag rechtlich der Verkäuferin gehören. Die Eltern haben das Geschenk für ihr Kind angenommen.","ask":"Wie antwortet Global Bike sachlich?","options":["Eigentum richtet sich hier danach, wer die Übergabe filmt.","Das Kind kann bereits vor dem siebten Geburtstag Rechte haben.","Die Eltern können als gesetzliche Vertreter für das Kind handeln.","Geschenke werden erst mit der Volljährigkeit rechtswirksam.","Bis sieben besteht nur ein Anspruch der Verkäuferin.","Die Kundschaft kann das Alter durch eine Rechnung bestätigen und voll geschäftsfähig machen."],"answer":[1,2],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Annahme durch die Vertreter ist vom Beginn der Rechtsfähigkeit zu trennen. Für das Kind entstandene Rechte setzen kein eigenes Erklären voraus.","hint":"Welche Frage klärt der siebte Geburtstag tatsächlich?","steps":"Unterstreiche die Person, die ein Recht erhalten kann. Prüfe getrennt, wer die Erklärung abgibt.","example":"Bei einem Geschenk kann das Kind Eigentümer sein, während die gesetzlichen Vertreter die Annahme erklären.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":12,"reserveNo":1},{"id":55,"l":2,"c":0,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"In der Kundendatei getrennt ausweisen","scene":"Übungsvariante: Ein Kind wurde vorgestern geboren. Die Eltern haben in seinem Namen ein Zubehörpaket angenommen. Im System gibt es getrennte Felder „Rechte für“ und „Erklärung abgegeben durch“.","ask":"Was trägst du ein?","options":["Rechte für: noch keine Person, bis das Kind selbst unterschreibt.","Rechte für: das Kind.","Erklärung abgegeben durch: die Eltern als Vertreter.","Erklärung abgegeben durch: niemand, weil niemand den Kaufpreis gezahlt hat.","Rechte für: die zweite Verkäuferin.","Erklärung abgegeben durch: das neugeborene Kind."],"answer":[1,2],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die beiden Felder dokumentieren unterschiedliche Rollen. Das Kind kann Rechte haben und die Eltern handeln für das Kind.","hint":"Lies zuerst jedes Feld und ordne dann die Beteiligten zu.","steps":"Unterstreiche die Person, die ein Recht erhalten kann. Prüfe getrennt, wer die Erklärung abgibt.","example":"Bei einem Geschenk kann das Kind Eigentümer sein, während die gesetzlichen Vertreter die Annahme erklären.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":12,"reserveNo":2},{"id":56,"l":2,"c":0,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Kind und Eltern unterscheiden","scene":"Übungsvariante: Ein Verkäufer trägt einen 4-Jährigen als Eigentümer eines geschenkten Fahrradhelms ein. Daneben steht „eigener Vertragsabschluss des Kindes noch offen“. Die Eltern haben das Geschenk für ihn angenommen.","ask":"Was ist bei der zweiten Aussage zu beachten?","options":["Ein Geschenk ist vor dem siebten Geburtstag nur möglich, wenn das Kind unterschreibt.","Die Eltern haben für das Kind gehandelt. Es musste das Geschenk nicht selbst annehmen.","Die Verkäuferunterschrift macht einen eigenen Kauf des Kindes wirksam.","Das Kind verliert sein Eigentum, wenn es keine eigenen Verträge abschließen kann.","Das Eigentum und ein späterer eigener Kauf sind getrennt zu behandeln.","Da das Geschenk legal ist, darf das Kind jedes Zubehör auf Rechnung kaufen."],"answer":[1,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Eltern handeln in der Geschenkannahme als Vertreter. Das bedeutet nicht, dass für weitere Geschäfte eine wirksame eigene Erklärung des Kindes möglich wird.","hint":"Trenne den bereits beschriebenen Vorgang von einem künftigen Geschäft.","steps":"Unterstreiche die Person, die ein Recht erhalten kann. Prüfe getrennt, wer die Erklärung abgibt.","example":"Bei einem Geschenk kann das Kind Eigentümer sein, während die gesetzlichen Vertreter die Annahme erklären.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":13,"reserveNo":1},{"id":57,"l":2,"c":0,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Eine Antwort für die Beratung auswählen","scene":"Übungsvariante: Eine 6-Jährige ist Eigentümerin ihres Rads. Für neues Fahrradzubehör gibt sie dem Verkauf selbst eine verbindlich klingende Bestellung. Emma soll Eigentum und Bestellung einordnen.","ask":"Welche Aussagen trägt Emma ein?","options":["Ihre eigene Erklärung zum Zubehör ist wegen ihres Alters nichtig.","Gerade weil die Bestellung nichtig ist, verliert das Kind das Fahrrad.","Das Kind ist rechtsfähig und kann deshalb Eigentümerin sein.","Die Bestellung gilt, weil sie das Fahrrad bereits besitzt.","Die Rechtsfähigkeit beginnt erst mit einer wirksamen Bestellung.","Die Eigentümerin ist durch den Besitz zwingend beschränkt geschäftsfähig."],"answer":[0,2],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Das Kind kann Rechte am Fahrrad haben. Unter sieben ist es geschäftsunfähig, sodass seine eigene Erklärung nichtig ist.","hint":"Prüfe zwei verschiedene Rechtsvorgänge, bevor du eine Gesamtaussage machst.","steps":"Unterstreiche die Person, die ein Recht erhalten kann. Prüfe getrennt, wer die Erklärung abgibt.","example":"Bei einem Geschenk kann das Kind Eigentümer sein, während die gesetzlichen Vertreter die Annahme erklären.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":13,"reserveNo":2},{"id":58,"l":2,"c":1,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Nicht dieselbe Stufe trotz Altersnähe","scene":"Übungsvariante: Global Bike erfasst zwei Kundinnen mit 6 und 7 Jahren. Beide bekommen für ihren Geburtstag einen Korb von ihren Eltern.","ask":"Welche altersbezogenen Aussagen stimmen ohne Blick auf spätere Käufe?","options":["Die Kundin mit 6 kann nicht rechtsfähig sein.","Die Kundin mit 7 ist gesetzlich volljährig.","Beide werden durch ein Geschenk voll geschäftsfähig.","Mit 6 ist die Kundin geschäftsunfähig.","Beide haben unabhängig vom Alter dieselbe Geschäftsfähigkeit.","Mit 7 ist die Kundin beschränkt geschäftsfähig."],"answer":[3,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Das Alter zum jeweiligen Zeitpunkt entscheidet über die Stufe. Die Schenkung ändert die Stufe nicht.","hint":"Stelle beide Altersangaben nebeneinander und markiere die gesetzliche Grenze.","steps":"Ordne zuerst das Alter am Tag des Geschäfts ein. Prüfe danach, von wem die Erklärung stammt.","example":"Das Alter einer Person wird am Tag der eigenen Erklärung geprüft. Ein späterer Geburtstag ändert den damaligen Stand nicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":14,"reserveNo":1},{"id":59,"l":2,"c":1,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Ein falscher Grenzwert im Infoblatt","scene":"Übungsvariante: Im Kurzblatt steht: „Bis einschließlich 7 geschäftsunfähig, ab 17 im Regelfall voll geschäftsfähig“.","ask":"Welche beiden Änderungen sind nötig?","options":["Beschränkte Geschäftsfähigkeit mit Alter 6 beginnen lassen.","„Die Stufen hängen vom Kaufpreis ab“ ergänzen.","„Geschäftsunfähig bis einschließlich 17“ einsetzen.","„Rechtsfähig erst ab 18“ ergänzen.","„Unter 7 geschäftsunfähig“ schreiben.","„Ab dem 18. Geburtstag im Regelfall voll geschäftsfähig“ schreiben."],"answer":[4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"§§ 2, 104, 106 BGB setzen die Grenzen bei Vollendung des siebten und achtzehnten Lebensjahres.","hint":"Vergleiche „unter sieben“ mit „bis einschließlich sieben“.","steps":"Ordne zuerst das Alter am Tag des Geschäfts ein. Prüfe danach, von wem die Erklärung stammt.","example":"Das Alter einer Person wird am Tag der eigenen Erklärung geprüft. Ein späterer Geburtstag ändert den damaligen Stand nicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":14,"reserveNo":2},{"id":60,"l":2,"c":1,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Zwei Kundensituationen auseinanderhalten","scene":"Übungsvariante: Die Verkäuferin vereinbart mit einem 6-Jährigen und, in einem getrennten Vorgang, mit einem 15-Jährigen jeweils einen Kauf auf Rechnung. Beide handeln selbst und ohne Einwilligung. Es wurde nichts gezahlt. Beim Älteren steht die Entscheidung der Eltern noch aus.","ask":"Welche Einträge treffen zu?","options":["Beide Erklärungen sind wegen einer offenen Rechnung nichtig.","Der ältere Kunde ist altersbedingt geschäftsunfähig.","Der jüngere Kunde kann mit der Rechnung seine Geschäftsfähigkeit beweisen.","Beide Verträge sind bereits wirksam.","Eigene Erklärung des Sechsjährigen: nichtig.","Vertrag des Fünfzehnjährigen: zunächst schwebend unwirksam."],"answer":[4,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Unter sieben ist die eigene Erklärung nichtig. Beim beschränkt geschäftsfähigen Jugendlichen kann die Genehmigung den noch offenen Fall entscheiden.","hint":"Prüfe jeden Vorgang zuerst über das Alter, dann über die Zustimmung.","steps":"Ordne zuerst das Alter am Tag des Geschäfts ein. Prüfe danach, von wem die Erklärung stammt.","example":"Das Alter einer Person wird am Tag der eigenen Erklärung geprüft. Ein späterer Geburtstag ändert den damaligen Stand nicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":15,"reserveNo":1},{"id":61,"l":2,"c":1,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Eine Vertretung für die Ersatzbestellung","scene":"Übungsvariante: Ein Kind mit 6 Jahren bestellt selbst eine Trinkflasche. Daraufhin gibt seine Mutter ausdrücklich in seinem Namen eine neue Bestellung ab.","ask":"Welche Beurteilung berücksichtigt beide Erklärungen?","options":["Die Mutter kann als gesetzliche Vertreterin für das Kind eine neue Erklärung abgeben.","Die erste eigene Erklärung bleibt nichtig.","Die erste Erklärung ist schwebend unwirksam und wird immer genehmigt.","Das Kind wird bei der zweiten Bestellung selbst voll geschäftsfähig.","Die Mutter kann durch bloßes Bezahlen die erste Erklärung des Kindes nach § 110 BGB wirksam machen.","Beide Erklärungen gelten als Erklärungen der Mutter."],"answer":[0,1],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die eigene nichtige Erklärung eines Geschäftsunfähigen und eine neue Erklärung durch einen Vertreter sind zwei verschiedene Vorgänge.","hint":"Achte bei jedem Satz darauf, wer ihn erklärt.","steps":"Ordne zuerst das Alter am Tag des Geschäfts ein. Prüfe danach, von wem die Erklärung stammt.","example":"Das Alter einer Person wird am Tag der eigenen Erklärung geprüft. Ein späterer Geburtstag ändert den damaligen Stand nicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":15,"reserveNo":2},{"id":62,"l":2,"c":2,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Eine Leihpflicht von einer Schenkung unterscheiden","scene":"Übungsvariante: Einer 15-Jährigen werden ein Sattelüberzug ohne Pflichten und ein zweiter Überzug zur Mitnahme angeboten. Für den zweiten müsste sie sich rechtlich verbindlich zur Rückgabe verpflichten.","ask":"Welche Beurteilung stimmt?","options":["Der zweite Vorgang enthält eine Rückgabepflicht und ist deshalb nicht nur vorteilhaft.","Beide Annahmen sind nur mit sofortiger Zahlung möglich.","Ohne Preis besteht nie eine rechtliche Pflicht.","Beim ersten Überzug entsteht keine rechtliche Verpflichtung durch die Annahme.","Der erste Überzug fällt automatisch unter § 110 BGB.","Der zweite Überzug ist wegen der Rückgabe besonders einfach und damit lediglich vorteilhaft."],"answer":[0,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Sofern die Rückgabe verbindlich vereinbart ist, entsteht eine Pflicht. Das unterscheidet ihn vom Geschenk ohne Bedingungen.","hint":"Prüfe die Bedingungen vor dem Preis.","steps":"Lies, welche Folgen die Annahme hat. Suche nach einer Geldzahlung oder einer anderen rechtlichen Pflicht.","example":"Ein Preisnachlass spart Geld. Beim Kauf bleibt trotzdem eine Zahlungspflicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":16,"reserveNo":1},{"id":63,"l":2,"c":2,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Kaputte Waren erklären das Ergebnis nicht","scene":"Übungsvariante: Ein 14-Jähriger bekommt einen gebrauchten Fahrradkorb ohne Pflichten. Der Verkäufer hält das Geschenk wegen eines Kratzers für rechtlich nachteilig. Der Korb kann verwendet werden.","ask":"Welche Aussagen klären die Frage?","options":["Je höher der Neupreis, desto wirksamer die Annahme.","Die Annahme ohne Pflichten bleibt in diesem Fall lediglich rechtlich vorteilhaft.","Gebrauchte Waren dürfen Minderjährige nie annehmen.","Der Kratzer mindert hier möglicherweise den wirtschaftlichen Wert.","Ein wirtschaftlicher Nachteil ist immer eine zusätzliche rechtliche Pflicht.","Der Korb muss bezahlt werden, weil er einen Kratzer hat."],"answer":[1,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Ein geringerer Wert kann wirtschaftlich eine Rolle spielen. Ob die Person eine rechtliche Pflicht übernimmt, ist eine andere Frage.","hint":"Vergleiche „weniger wert“ mit „zur Leistung verpflichtet“.","steps":"Lies, welche Folgen die Annahme hat. Suche nach einer Geldzahlung oder einer anderen rechtlichen Pflicht.","example":"Ein Preisnachlass spart Geld. Beim Kauf bleibt trotzdem eine Zahlungspflicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":16,"reserveNo":2},{"id":64,"l":2,"c":2,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Ein Null-Euro-Preis mit Zusatzkosten","scene":"Übungsvariante: Ein 16-Jähriger möchte ein als „0 Euro“ beworbenes Licht bestellen. Der Vertrag verpflichtet ihn aber zur Zahlung von 6 Euro Versandkosten.","ask":"Warum genügt im Verkauf der Hinweis „gratis“ nicht zur Einordnung?","options":["Eine Online-Anzeige ersetzt jede elterliche Zustimmung.","Erst ab 20 Euro gilt eine Zahlung als rechtlich relevant.","Die Versandkosten sind eine vereinbarte Zahlungspflicht.","Versandkosten können nie Teil einer Vertragspflicht sein.","Die Annahme kann deshalb nicht allein wegen der Überschrift lediglich rechtlich vorteilhaft genannt werden.","Ein Preis von null macht jede weitere Vertragsbedingung unwirksam."],"answer":[2,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Es kommt auf den vollständigen Inhalt der Vereinbarung an. Die übernommenen Versandkosten sind eine rechtliche Verpflichtung.","hint":"Lies auch, was unter der Überschrift als Pflicht steht.","steps":"Lies, welche Folgen die Annahme hat. Suche nach einer Geldzahlung oder einer anderen rechtlichen Pflicht.","example":"Ein Preisnachlass spart Geld. Beim Kauf bleibt trotzdem eine Zahlungspflicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":17,"reserveNo":1},{"id":65,"l":2,"c":2,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Zwei Preisschilder und dieselbe Prüffrage","scene":"Übungsvariante: Ein 15-Jähriger betrachtet zwei Schlösser zu 9,90 Euro und 59,90 Euro. Beide möchte er ohne Einwilligung auf Rechnung bestellen.","ask":"Welche Aussagen gelten für beide Angebote?","options":["Das teure Schloss kann grundsätzlich nie rechtswirksam gekauft werden.","Beim günstigeren Schloss entsteht keine Gegenleistung.","Die erforderliche Zustimmung ist unabhängig vom günstigeren Preisschild zu prüfen.","Keiner der Preisbeträge macht den offenen Rechnungskauf allein wirksam.","Jede Bestellung kann eine Zahlungspflicht begründen.","Für 9,90 Euro gilt eine automatische Freigrenze."],"answer":[2,3,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Für Kaufangebote beider Preise ist die rechtliche Pflicht zu prüfen. Eine allgemeine Preisgrenze ersetzt die Prüfung der Zustimmung nicht.","hint":"Vergleiche zuerst die Art der Verpflichtung, dann die tatsächliche Wirkung des Preises.","steps":"Lies, welche Folgen die Annahme hat. Suche nach einer Geldzahlung oder einer anderen rechtlichen Pflicht.","example":"Ein Preisnachlass spart Geld. Beim Kauf bleibt trotzdem eine Zahlungspflicht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":17,"reserveNo":2},{"id":66,"l":2,"c":3,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Eine Unterschrift zuordnen","scene":"Übungsvariante: Ein Lagervermerk behauptet, die Zustimmung vom Donnerstag sei beim Kauf am Mittwoch schon „vorher erteilt“ gewesen. Es gab vor Mittwoch keine weitere Zustimmung.","ask":"Welche Korrekturen sind begründet?","options":["Die Zeitfolge ergibt sich aus Abschlussdatum und Zustimmungsdatum.","Der Donnerstag ist rechtlich immer der Vertragsbeginn.","Die spätere Zustimmung ist keine Form der Zustimmung.","Die Eltern hätten erst bei Lieferung zustimmen dürfen.","Die Zustimmung vom Donnerstag ist als Genehmigung zu dokumentieren.","Die Uhrzeit des Lagervermerks macht die Zustimmung zur Einwilligung."],"answer":[0,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Genehmigung erfolgt später als der Vertrag. Für die Dokumentation zählt das tatsächliche Datum der Erklärung.","hint":"Markiere zuerst, wann der Vertrag zu Stande kam.","steps":"Markiere den Zeitpunkt des Vertrags und den Stand der Zustimmung. Entscheide erst danach, ob der Fall offen ist.","example":"Die Einwilligung liegt vor dem Vertrag. Eine erst danach erteilte Zustimmung heißt Genehmigung.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":18,"reserveNo":1},{"id":67,"l":2,"c":3,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Zwei erlaubte Wege zur Wirksamkeit","scene":"Übungsvariante: Bei Auftrag A sagen die Eltern vor der Bestellung zu. Bei Auftrag B genehmigen sie den zuvor ohne Einwilligung geschlossenen Vertrag nachträglich. Es handelt sich um gleich große Beträge, die noch nicht gezahlt sind.","ask":"Welche Aussagen passen zum Vergleich?","options":["Beide Vorgänge enthalten eine Zustimmung in unterschiedlicher zeitlicher Reihenfolge.","Die gleiche Summe macht beide Zustimmungstypen gleich.","B wird im Regelfall durch Genehmigung rückwirkend wirksam.","Für A und B ist vollständige Barzahlung die einzige Möglichkeit.","B ist wegen der nachträglichen Zustimmung eine Einwilligung.","A ist durch Einwilligung gedeckt."],"answer":[0,2,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Beträge entscheiden nicht über die Bezeichnung. Maßgeblich ist, wann die Zustimmung erteilt wurde.","hint":"Skizziere in beiden Fällen eine kurze Zeitachse.","steps":"Markiere den Zeitpunkt des Vertrags und den Stand der Zustimmung. Entscheide erst danach, ob der Fall offen ist.","example":"Die Einwilligung liegt vor dem Vertrag. Eine erst danach erteilte Zustimmung heißt Genehmigung.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":18,"reserveNo":2},{"id":68,"l":2,"c":3,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Bedingung der Eltern übersehen","scene":"Übungsvariante: Ein 14-Jähriger darf ein Licht bis 30 Euro kaufen und soll bar bezahlen. Ohne weitere Zustimmung wählt er dasselbe Licht für 24 Euro auf Rechnung. Nichts ist bezahlt. Die Eltern haben noch nicht entschieden.","ask":"Welche Schlussfolgerungen passen?","options":["Der Vertrag ist wegen der Rechnung sofort endgültig unwirksam.","Der niedrigere Preis hebt die Barzahlungsbedingung auf.","Die Wirksamkeit hängt hier noch von der Genehmigung ab.","Die Rechnungszahlung ist von der Einwilligung nicht umfasst.","§ 110 BGB ist erfüllt, obwohl noch nichts gezahlt wurde.","Der Preis erfüllt den vereinbarten Höchstwert."],"answer":[2,3,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Zustimmung umfasste eine andere Zahlungsweise. Für den Rechnungskauf fehlt damit eine nötige Einwilligung.","hint":"Lies die Vorgaben zum Betrag und zur Zahlungsart als zwei Bedingungen.","steps":"Markiere den Zeitpunkt des Vertrags und den Stand der Zustimmung. Entscheide erst danach, ob der Fall offen ist.","example":"Die Einwilligung liegt vor dem Vertrag. Eine erst danach erteilte Zustimmung heißt Genehmigung.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":19,"reserveNo":1},{"id":69,"l":2,"c":3,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Das erlaubte Produkt mit der Bestellung vergleichen","scene":"Übungsvariante: Die Eltern eines 16-Jährigen stimmen vorab dem Kauf einer Rahmentasche für 35 Euro auf Rechnung zu. Er bestellt ohne weitere Zustimmung stattdessen einen Fahrradcomputer zum gleichen Preis. Die Rechnung bleibt offen.","ask":"Wie prüfst du die Einwilligung?","options":["Der offene Rechnungskauf ist wegen seiner Höhe bereits wirksam.","Der Fahrradcomputer ist automatisch ein Geschenk.","Die Eltern hätten den Kaufgegenstand erst nach dem Bezahlen nennen dürfen.","Der gleiche Preis ersetzt die Zustimmung zum anderen Kaufgegenstand nicht.","Sie bezog sich auf die Rahmentasche.","Die Einwilligung gilt für jedes Produkt mit gleichem Preis."],"answer":[3,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Bei einer auf einen Artikel begrenzten Einwilligung muss die Bestellung dazu passen. Gleicher Preis und gleiche Zahlungsweise reichen nicht.","hint":"Prüfe, worauf sich die Zustimmung ihrem Wortlaut nach bezieht.","steps":"Markiere den Zeitpunkt des Vertrags und den Stand der Zustimmung. Entscheide erst danach, ob der Fall offen ist.","example":"Die Einwilligung liegt vor dem Vertrag. Eine erst danach erteilte Zustimmung heißt Genehmigung.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":19,"reserveNo":2},{"id":70,"l":2,"c":3,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Nachfragen ohne Freigabe","scene":"Übungsvariante: Eine 15-Jährige bestellt ohne Einwilligung auf Rechnung. Die Eltern möchten die Bedingungen erst lesen. Es gab weder eine Aufforderung zur Erklärung im Rechtssinn noch eine Zahlung.","ask":"Welche Aussagen gehören in die Zwischennotiz?","options":["Weil die Eltern nachfragen, ist die Kundin voll geschäftsfähig.","Ein bloßer Wunsch nach Informationen ist hier keine Verweigerung.","Die Wirksamkeit hängt weiter von der Genehmigung ab.","Die Rückfrage gilt als Genehmigung.","Die Eltern haben noch keine Genehmigung erteilt.","Die Bestellung ist schon endgültig unwirksam."],"answer":[1,2,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Eine Informationsfrage kann die Prüfung vorbereiten. Im Fall ändert sie den offenen Status nicht.","hint":"Unterscheide Interesse an Unterlagen von einer Ja- oder Nein-Entscheidung.","steps":"Markiere den Zeitpunkt des Vertrags und den Stand der Zustimmung. Entscheide erst danach, ob der Fall offen ist.","example":"Die Einwilligung liegt vor dem Vertrag. Eine erst danach erteilte Zustimmung heißt Genehmigung.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":20,"reserveNo":1},{"id":71,"l":2,"c":3,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Ausstehend, genehmigt und abgelehnt","scene":"Übungsvariante: Drei 16-Jährige bestellen in getrennten Fällen ohne Einwilligung auf Rechnung. Alle Rechnungen sind offen. A hat noch keine Antwort, B wird nachträglich genehmigt, C wird ausdrücklich abgelehnt.","ask":"Welche Zuordnung dokumentiert die Vorgänge?","options":["B ist durch die nachträgliche Genehmigung wirksam.","C gilt durch die Ablehnung als genehmigt.","A ist wegen der offenen Rechnung bereits wirksam.","A bleibt schwebend unwirksam.","B bleibt trotz Genehmigung bis zur Volljährigkeit unwirksam.","C ist endgültig unwirksam."],"answer":[0,3,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Die Vertragsstände unterscheiden sich nach der Reaktion der Vertreter. Die offene Rechnung ersetzt die Zustimmung in keinem Fall.","hint":"Schreibe zu A, B und C jeweils den Zeitpunkt und die Entscheidung.","steps":"Markiere den Zeitpunkt des Vertrags und den Stand der Zustimmung. Entscheide erst danach, ob der Fall offen ist.","example":"Die Einwilligung liegt vor dem Vertrag. Eine erst danach erteilte Zustimmung heißt Genehmigung.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":20,"reserveNo":2},{"id":72,"l":2,"c":4,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Ein Systemvermerk zur Freigrenze","scene":"Übungsvariante: Im Shop steht „Käufe unter 50 Euro gelten automatisch“. Ein 16-Jähriger zahlt 28 Euro vollständig mit Geld aus unbekannter Quelle. Eine Kaufzustimmung ist nicht dokumentiert.","ask":"Welche Berichtigungen sind fachlich begründet?","options":["Wenn der Betrag nur gerade Euro enthält, ist der Vertrag wirksam.","Die Herkunft und zulässige Verwendung der Mittel müssen noch geklärt werden.","Das Alter erklärt bereits die Herkunft des Geldes.","Eine allgemeine 50-Euro-Grenze folgt nicht aus § 110 BGB.","Unterhalb von 50 Euro genügt der Beleg über die Zahlung.","Eine Barzahlung belegt stets die freie Verfügung."],"answer":[1,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Vollständige Leistung ist belegt. Über die erforderliche Überlassung der Mittel sagt der Betrag nichts aus.","hint":"Was weißt du über den Geldbetrag, was über seine Herkunft?","steps":"Prüfe zuerst, ob die Leistung vollständig vorliegt. Vergleiche dann Herkunft und erlaubte Verwendung aller eingesetzten Mittel.","example":"Wer nur die erste von zwei Raten zahlt, hat die vereinbarte Leistung noch nicht vollständig erbracht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":21,"reserveNo":1},{"id":73,"l":2,"c":4,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Einen gemischten Zahlungsfall bewerten","scene":"Übungsvariante: Für ein Schloss zahlt eine 15-Jährige 18 Euro vollständig. Zwölf Euro stammen von den Eltern zur freien Verfügung. Sechs Euro gab eine erwachsene Bekannte ohne deren Zustimmung. Zum Kauf gibt es keine Einwilligung.","ask":"Was folgt für die Prüfung?","options":["Beim zweiten Teilbetrag fehlt die Zustimmung zur Überlassung durch die Dritte.","Eine Zahlung über zwölf Euro macht jede Herkunft wirksam.","Die vollständige Leistung erfolgte daher nicht vollständig mit zulässig überlassenen Mitteln.","Der erste Teilbetrag steht zur freien Verfügung.","Der überwiegende Geldanteil genügt stets für § 110 BGB.","Geld von Erwachsenen genügt unabhängig von der Zustimmung der Vertreter."],"answer":[0,2,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Der Kaufpreis ist zwar bezahlt. Nicht alle dafür eingesetzten Mittel entsprechen aber der gesetzlichen Voraussetzung.","hint":"Analysiere beide Geldteile mit demselben Maßstab.","steps":"Prüfe zuerst, ob die Leistung vollständig vorliegt. Vergleiche dann Herkunft und erlaubte Verwendung aller eingesetzten Mittel.","example":"Wer nur die erste von zwei Raten zahlt, hat die vereinbarte Leistung noch nicht vollständig erbracht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":21,"reserveNo":2},{"id":74,"l":2,"c":4,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Andere passende Mittel verwendet","scene":"Übungsvariante: Ein 16-Jähriger will 25 Euro für ein Schloss zahlen. Die Eltern gaben ihm 30 Euro für Schulhefte und zusätzlich 25 Euro zur freien Verfügung. Er verwendet nachweislich nur die frei verfügbaren 25 Euro und bezahlt vollständig. Eine Zustimmung zum Kauf wurde weder erteilt noch verweigert.","ask":"Welche Angaben sind für § 110 BGB entscheidend?","options":["Er hat vollständig mit frei verfügbaren Mitteln der Eltern gezahlt.","Weil der Schulumschlag voller ist, wird die Zahlung ihm zugerechnet.","Das ungenutzte zweckgebundene Geld steht diesem Vorgang nicht entgegen.","Das Geld für Schulhefte macht jedes andere Geld ebenfalls zweckgebunden.","Der Kauf ist unabhängig von den verwendeten Mitteln unwirksam.","Nur ein ausdrücklicher Zweck „Schloss“ hätte denselben Kauf erlaubt."],"answer":[0,2],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Es kommt auf die tatsächlich eingesetzten Mittel an. Frei überlassene Mittel können für den Kauf genutzt werden.","hint":"Prüfe nicht nur, welches Geld vorhanden war, sondern welches genutzt wurde.","steps":"Prüfe zuerst, ob die Leistung vollständig vorliegt. Vergleiche dann Herkunft und erlaubte Verwendung aller eingesetzten Mittel.","example":"Wer nur die erste von zwei Raten zahlt, hat die vereinbarte Leistung noch nicht vollständig erbracht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":22,"reserveNo":1},{"id":75,"l":2,"c":4,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Gleiche Preise, verschiedene Geldquellen","scene":"Übungsvariante: Zwei 15-Jährige kaufen jeweils ein Schloss für 20 Euro, zahlen vollständig und haben keine Kaufzustimmung. A nutzt Geld ihrer Eltern zur freien Verfügung. B verwendet Geld, das nur für den Schulweg mit dem Bus bestimmt ist. Die Eltern müssen noch entscheiden, ob sie Bs Kauf genehmigen.","ask":"Welche Fallbeurteilungen stimmen?","options":["B verwendet die Mittel außerhalb des erlaubten Zwecks.","A erfüllt die Voraussetzungen des § 110 BGB.","Beide Vorgänge sind allein wegen des gleichen Preises gleich zu behandeln.","B bleibt ohne eine Genehmigung zunächst schwebend unwirksam.","Bs Geld ist frei verwendbar, weil sie auch mit dem Rad zur Schule fahren könnte.","Beide Verträge sind wegen ihres Alters nichtig."],"answer":[0,1,3],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Der gezahlte Betrag ist gleich, aber der erlaubte Verwendungszweck ist verschieden. Nur A zahlt mit dafür zugelassenen Mitteln.","hint":"Vergleiche die Herkunft und den Zweck pro Fall.","steps":"Prüfe zuerst, ob die Leistung vollständig vorliegt. Vergleiche dann Herkunft und erlaubte Verwendung aller eingesetzten Mittel.","example":"Wer nur die erste von zwei Raten zahlt, hat die vereinbarte Leistung noch nicht vollständig erbracht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":22,"reserveNo":2},{"id":76,"l":2,"c":4,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Noch zehn Euro offen","scene":"Übungsvariante: Ein 16-Jähriger hat ohne Einwilligung einen Kauf von Zubehör für 60 Euro vereinbart. Er zahlt 50 Euro mit Geld, das ihm die Eltern zur freien Verfügung überlassen haben. Zehn Euro sind weiterhin offen. Die Eltern haben weder genehmigt noch abgelehnt.","ask":"Welche Schlussfolgerungen sind begründet?","options":["Die fehlenden zehn Euro verhindern jetzt die vollständige Leistung.","Der Vertrag ist damit noch nicht über § 110 BGB wirksam.","50 Euro gelten bereits als vollständige Zahlung wegen einer gesetzlichen Preisgrenze.","Durch die Teilzahlung wird der Vertrag endgültig unwirksam.","Der Händler kann die offene Rate in der Prüfung ignorieren.","Die bereits gezahlten 50 Euro stammen aus Mitteln, die die Eltern zur freien Verfügung überlassen haben."],"answer":[0,1,5],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Teilzahlung und vollständige Leistung unterscheiden sich. Die zulässigen Mittel ersetzen die offene Restleistung nicht.","hint":"Ziehe die gezahlte Summe von der vereinbarten Summe ab.","steps":"Prüfe zuerst, ob die Leistung vollständig vorliegt. Vergleiche dann Herkunft und erlaubte Verwendung aller eingesetzten Mittel.","example":"Wer nur die erste von zwei Raten zahlt, hat die vereinbarte Leistung noch nicht vollständig erbracht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":23,"reserveNo":1},{"id":77,"l":2,"c":4,"type":"multi","caseLabel":"LS 2.3 · Rechtliche Grundlagen für Kaufverträge (Theorie)","title":"Die letzte Rate aus zweckgebundenem Geld","scene":"Übungsvariante: Ein 17-Jähriger bezahlt alle drei Raten ohne Einwilligung. Für die ersten beiden nutzt er freies Taschengeld, für die letzte Geld seiner Eltern, das ausschließlich für Schulhefte gedacht ist. Keine Genehmigung wurde erteilt oder verweigert.","ask":"Welche Angaben stimmen?","options":["Die drei Raten sind als Beträge vollständig bezahlt.","Vollständigkeit genügt stets unabhängig von der Herkunft.","Zweckbindung spielt nur bei einmaliger Zahlung eine Rolle.","Die letzte Zahlung verwendet Mittel außerhalb ihres Zwecks.","§ 110 BGB erfasst den Vertrag unter diesen Umständen nicht.","Die ersten beiden Zahlungen machen die dritte automatisch zulässig."],"answer":[0,3,4],"criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","why":"Beide Voraussetzungen müssen miteinander vorliegen. Eine vollständig gezahlte Summe kann dennoch aus unzulässig eingesetzten Mitteln stammen.","hint":"Prüfe nicht nur die Summe, sondern auch jede Zahlung getrennt.","steps":"Prüfe zuerst, ob die Leistung vollständig vorliegt. Vergleiche dann Herkunft und erlaubte Verwendung aller eingesetzten Mittel.","example":"Wer nur die erste von zwei Raten zahlt, hat die vereinbarte Leistung noch nicht vollständig erbracht.","sourceRefs":["Handlungssituation","Ü1","Ü2","Ü3"],"coreId":23,"reserveNo":2}];
